/* credit-terms.js — generated by scripts/build-credit-terms.mjs from
   frontend/data/pc/glossary.json. Do not edit; edit the JSON and re-run.
   299 terms, glossary dated 2026-09-11. */
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.RTTerms = factory();
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  var VERSION = "2026-09-11";
  var TERMS = [
{"term":"10-K","kind":"regulation","side":"lender","popup":"The annual report. It carries the full-year figures, the tax note with spillover, the advisory-agreement note with the fee schedule, and whether the BDC elected 150% coverage.","source":"SEC Form 10-K general instructions (sec.gov); the BDC's 10-K advisory-agreement note; this site's derived-Q4 rule"},
{"term":"10-Q","kind":"regulation","side":"lender","popup":"The quarterly report. For a BDC it holds the balance sheet, income statement, schedule of investments, fee and tax notes, the asset-coverage sentence and the rate-sensitivity table.","source":"SEC Form 10-Q general instructions (sec.gov); BXSL 10-Q 2026-06-30; this site's differencing rule"},
{"term":"10y-2y curve","expansion":"Treasury yield curve slope","kind":"metric","side":"market","popup":"The slope of the Treasury curve: 10-year yield minus 2-year. Below zero the curve is inverted, which has come before most US recessions.","source":"FRED Notes for T10Y2Y (fetched 2026-09-11)"},
{"term":"150%/200% election","kind":"regulation","side":"lender","popup":"A BDC's borrowing limit is 200% asset coverage (1:1 debt to equity) unless its board or shareholders took the 2018 option to drop to 150% (about 2:1). 14 of the 19 exchange-listed BDCs tagging the ratio report under 200% (frames CY2026Q2I).","source":"15 U.S.C. §80a-60(a)(1)-(2) (law.cornell.edu); BXSL 10-Q 2026-06-30; SEC XBRL frames CY2026Q2I and the SEC submissions feed (exchange field), fetched 2026-09-11"},
{"term":"1940 Act","expansion":"Investment Company Act of 1940","kind":"regulation","side":"lender","popup":"The federal law that governs funds and BDCs. For a BDC it sets the borrowing limit (asset coverage), the rule against selling shares below NAV, and the definitions of control and affiliation.","source":"law.cornell.edu/uscode/text/15/80a-18, 80a-60, 80a-62, 80a-2 (fetched 2026-09-11); BXSL 10-Q 2026-06-30, Note 1"},
{"term":"8-K exhibit 99.1","kind":"regulation","side":"lender","popup":"The earnings release a company attaches to its 8-K. For BDCs it often carries figures the 10-Q lacks, such as core NII and borrower leverage; yields on new loans appear in either.","source":"SEC Form 8-K instructions (sec.gov/files/form8-k.pdf), Items 2.02 and 9.01"},
{"term":"90% distribution test","kind":"regulation","side":"lender","popup":"To stay tax-free at the fund level, a BDC must pay out at least 90% of its taxable investment income every year. This is why dividends track NII so closely.","source":"BXSL 10-Q 2026-06-30"},
{"term":"ABF","expansion":"Asset-based finance","kind":"market","side":"market","popup":"Asset-based finance: lending secured by pools of specific assets, such as consumer loans, leases, receivables or equipment, rather than by a company's cash flow.","source":"PitchBook 2023 Annual Global Private Debt Report"},
{"term":"accrued capex","kind":"metric","side":"both","popup":"Property and equipment received but not yet paid for. A timing item that becomes cash capex next quarter and explains gaps between quoted and cash capex.","source":"us-gaap taxonomy element CapitalExpendituresIncurredButNotYetPaid; the cash-flow statement's supplemental non-cash disclosures","aliases":["capex incurred but not yet paid"]},
{"term":"add-on","expansion":"add-on acquisition","kind":"market","side":"market","popup":"An acquisition bolted onto a sponsor-owned platform company, usually funded by drawing a delayed-draw term loan or an incremental facility. Buy-and-build strategies string several together.","source":"PitchBook Q3 2025 Analyst Note: From Peak to Pivot","aliases":["add-ons","buy-and-build"]},
{"term":"adjusted close","kind":"metric","side":"both","popup":"The closing price restated so that dividends and splits are reinvested: a total-return series. For a BDC ETF paying a high yield it runs far above the plain price over five years.","source":"Yahoo chart v8, indicators.adjclose (query1.finance.yahoo.com/v8/finance/chart/BIZD?range=5y&interval=1mo); Yahoo Finance help, 'What is the adjusted close?' (help.yahoo.com/kb/SLN28256.html)","aliases":["adjusted closes","adjclose"]},
{"term":"after-tax NII","kind":"metric","side":"lender","popup":"Net investment income after the fund's income and excise taxes. This is the GAAP figure and the one the press release quotes; some filers tag NII before tax, so the site records which line answered.","source":"us-gaap taxonomy elements InvestmentIncomeOperatingAfterExpenseAndTax, NetInvestmentIncome and InvestmentIncomeOperatingTaxExpenseBenefit on SEC EDGAR companyfacts (ARCC, BXSL and MAIN, Q2 2026)"},
{"term":"All-in rate","expansion":"All-in yield","kind":"metric","side":"market","popup":"What a loan actually pays: base rate plus spread, after any floor. LCD's BDC chart tracks the cost-weighted average all-in interest rate on loans BDCs hold.","source":"LCD US Private Credit Monitor, August 2026, slide 33 title and chartHeading"},
{"term":"Amend-and-extend","expansion":"A&E","kind":"market","side":"market","popup":"Lenders agree to push a loan's maturity out, usually for a higher spread or a fee, instead of the borrower refinancing. It moves a loan on the maturity wall without repaying it.","source":"Usage: PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026. Definition is standard."},
{"term":"amortized cost","kind":"metric","side":"lender","popup":"What the BDC paid for a loan, adjusted over time for any discount or fees it accretes into income. It is the 'cost' side of every mark and yield calculation.","source":"BXSL 10-Q 2026-06-30"},
{"term":"asset coverage","kind":"regulation","side":"lender","popup":"The 1940 Act's leverage test: (total assets − liabilities other than debt) ÷ debt. A BDC must stay at or above 150% (or 200%) to borrow more. BXSL was at 178% on June 30, 2026.","source":"15 U.S.C. §80a-18(h) and §80a-60(a) (law.cornell.edu); BXSL 10-Q 2026-06-30"},
{"term":"attach point","kind":"metric","side":"lender","popup":"The level of leverage at which a lender's claim begins. A bank loan attaches at 4.5-5.0x EBITDA; a unitranche may attach at 6.0-7.0x, so equity and junior debt must be wiped out first before it loses.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"Attachment point","kind":"metric","side":"market","popup":"The leverage, in turns of EBITDA, at which a loan's exposure sits. A unitranche that goes to 6 to 7x EBITDA is hit sooner than a bank loan that stops at 4.5 to 5x, because the company's value has less room to fall.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"AUM","expansion":"Assets under management","kind":"metric","side":"market","popup":"Assets under management: what a manager's funds hold, at current value, plus the dry powder still to be called.","source":"PitchBook 2024 Annual Global Private Debt Report"},
{"term":"B","expansion":"Single-B","kind":"acronym","side":"market","popup":"Single-B: the middle of high yield and the typical rating of a leveraged-buyout borrower. LCD's BSL comparisons often use B-minus loans.","source":"ICE definition via FRED Notes for BAMLH0A2HYB; LCD US Private Credit Monitor, August 2026, slide 14 footnote; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights; rating-scale mapping is standard"},
{"term":"Baa","kind":"acronym","side":"market","popup":"Moody's lowest investment-grade band, equal to BBB at S&P and Fitch. The Baa bond yield is the classic gauge of borrowing costs for an average large company.","source":"FRED Notes for BAA10Y (fetched 2026-09-11); rating-scale mapping is standard"},
{"term":"BAA10Y","expansion":"Moody's Baa Corporate Bond Yield minus 10-Year Treasury","kind":"series-id","side":"market","popup":"The gap between yields on Baa-rated corporate bonds and the 10-year Treasury. A long-run measure of how much extra the market charges a decent, not great, company to borrow.","source":"FRED series page https://fred.stlouisfed.org/series/BAA10Y, Notes block, fetched 2026-09-11"},
{"term":"backlog to debt","kind":"metric","side":"both","popup":"Contracted future revenue divided by gross debt. Undiscounted revenue over multi-year terms against borrowings; above 1 is collateral, not cover, and it is only as good as the counterparty.","source":"us-gaap taxonomy elements RevenueRemainingPerformanceObligation and LessorOperatingLeasePaymentsToBeReceived; this site's own ratio","aliases":["backlog cover"]},
{"term":"backstop","kind":"instrument","side":"both","popup":"A guarantee by a hyperscaler of a tenant's lease payments to a developer. The credit behind the developer's bonds is the guarantor, not the tenant, so the guarantor's rating sizes the notes.","source":"us-gaap taxonomy element GuaranteeObligationsMaximumExposure; the filer's guarantees note as printed","aliases":["backstops","lease backstop"]},
{"term":"BAMLC0A0CM","expansion":"ICE BofA US Corporate Index Option-Adjusted Spread","kind":"series-id","side":"market","popup":"Investment-grade bond spread. The extra yield over Treasuries on bonds rated BBB or better. It is the calmest corner of credit; when it moves, everything else is moving more.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLC0A0CM, Notes block, fetched 2026-09-11"},
{"term":"BAMLH0A0HYM2","expansion":"ICE BofA US High Yield Index Option-Adjusted Spread","kind":"series-id","side":"market","popup":"High-yield bond spread. How much extra yield, over Treasuries, investors demand to hold US junk bonds. Under 3 points is tight; over 5 is stress.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLH0A0HYM2, Notes block, fetched 2026-09-11; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figure 94)"},
{"term":"BAMLH0A0HYM2EY","expansion":"ICE BofA US High Yield Index Effective Yield","kind":"series-id","side":"market","popup":"The all-in yield on US junk bonds, not just the spread. This is what a liquid, tradeable alternative to a private loan pays today.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLH0A0HYM2EY, Notes block, fetched 2026-09-11"},
{"term":"BAMLH0A1HYBB","expansion":"ICE BofA BB US High Yield Index Option-Adjusted Spread","kind":"series-id","side":"market","popup":"Spread on BB-rated bonds, the best-quality junk. The top rung of the high-yield ladder; the gap between this and CCC shows how far the market separates good and bad borrowers.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLH0A1HYBB, Notes block, fetched 2026-09-11"},
{"term":"BAMLH0A2HYB","expansion":"ICE BofA Single-B US High Yield Index Option-Adjusted Spread","kind":"series-id","side":"market","popup":"Spread on single-B bonds. The middle of the junk-bond ladder and the closest public match to a typical private-credit borrower, which is usually rated B or not rated at all.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLH0A2HYB, Notes block, fetched 2026-09-11"},
{"term":"BAMLH0A3HYC","expansion":"ICE BofA CCC & Lower US High Yield Index Option-Adjusted Spread","kind":"series-id","side":"market","popup":"Spread on CCC and lower bonds, the riskiest rated debt. It jumps first and furthest in a downturn, so its distance from BB is the market's fear gauge.","source":"FRED series page https://fred.stlouisfed.org/series/BAMLH0A3HYC, Notes block, fetched 2026-09-11"},
{"term":"Base rate","kind":"market","side":"market","popup":"The floating reference rate a loan is priced over. Today that is SOFR for dollar loans (SONIA for sterling, EURIBOR for euro); the lender's margin is added on top.","source":"FRED Notes for DPRIME"},
{"term":"BB","kind":"acronym","side":"market","popup":"The top rung of high yield, one notch below investment grade. Solid companies with more debt than an IG rating allows.","source":"ICE definition via FRED Notes for BAMLH0A1HYBB (fetched 2026-09-11); rating-scale mapping is standard"},
{"term":"BDC","expansion":"business development company","kind":"acronym","side":"lender","popup":"A listed lender that raises money from public shareholders and lends it to mid-sized private US companies. It files with the SEC like any public company and is regulated under the 1940 Act.","source":"15 U.S.C. §80a-2(a)(48) (law.cornell.edu, fetched 2026-09-11); BXSL 10-Q 2026-06-30, Note 1"},
{"term":"BIZD","expansion":"VanEck BDC Income ETF","kind":"instrument","side":"both","popup":"The exchange-traded fund that holds the listed BDCs, so its price is the one daily public quote on private credit books. Chart M8 draws it rebased to 100 against a loan ETF.","source":"Yahoo chart v8 for BIZD, meta.longName and 61 monthly timestamps (query1.finance.yahoo.com/v8/finance/chart/BIZD?range=5y&interval=1mo, fetched 2026-09-11); VanEck fund page for BIZD (vaneck.com)"},
{"term":"BKLN","expansion":"Invesco Senior Loan ETF","kind":"instrument","side":"market","popup":"The Invesco Senior Loan ETF, an exchange-traded fund of syndicated senior loans. The alternative to SRLN as the loan-market line on chart M8.","source":"Yahoo chart v8 for BKLN, meta.longName (fetched 2026-09-11); Invesco fund page for BKLN (invesco.com)"},
{"term":"bps","expansion":"Basis points","kind":"metric","side":"market","popup":"Basis points. One basis point is one hundredth of a percent, so 500 bps is 5.00%. Spreads are quoted in bps.","source":"Standard definition; not defined in the study material or on a fetched page"},
{"term":"Bridge financing","kind":"market","side":"market","popup":"Short-term loans made while longer financing is arranged, also called swing loans. One of PitchBook's nine private debt fund types.","source":"PitchBook 2024 Annual Global Private Debt Report, 'Fund type definitions'","aliases":["bridge loan","swing loan"]},
{"term":"Broadly syndicated loan","kind":"market","side":"market","popup":"See BSL. A bank-arranged loan sold to many lenders and traded afterwards, as opposed to a direct loan held by one lender or a small club.","source":"LCD US Private Credit Monitor, August 2026, slide 43 methodology (direct lending 'not broadly syndicated')"},
{"term":"BSL","expansion":"Broadly syndicated loan","kind":"market","side":"market","popup":"Broadly syndicated loan: a large loan arranged by a bank and sold in pieces to many investors, mainly CLOs. It trades, it is rated, and it is the public rival to direct lending.","source":"LCD US Private Credit Monitor, August 2026, slides 14-16 footnotes; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"business development company","kind":"regulation","side":"lender","popup":"The legal form behind every lender on this page: a US closed-end fund that elected BDC status, lends mostly to private companies, offers them managerial help, and lives under the 1940 Act's leverage cap.","source":"15 U.S.C. §80a-2(a)(48) (law.cornell.edu); BXSL 10-Q 2026-06-30, Note 1; SEC BDC data set readme.htm (2026_07_bdc.zip, sec.gov), Scope: 'file number beginning with 814-'","aliases":["business development companies"]},
{"term":"BUSLOANS","expansion":"Commercial and industrial loans, all commercial banks","kind":"series-id","side":"market","popup":"Total business loans on US bank balance sheets, in billions of dollars. The size of the bank channel that private credit competes with.","source":"FRED series page https://fred.stlouisfed.org/series/BUSLOANS, Notes block, fetched 2026-09-11"},
{"term":"C&I","expansion":"Commercial and industrial","kind":"acronym","side":"market","popup":"Commercial and industrial loans: bank loans to businesses for operations and investment, as opposed to real estate or consumer loans.","source":"FRED series titles for BUSLOANS, DRTSCILM, DRSDCILM (fetched 2026-09-11)"},
{"term":"CAGR","expansion":"compound annual growth rate","kind":"acronym","side":"both","popup":"The steady yearly growth rate that would take a series from its first value to its last: (end ÷ start)^(1 ÷ years) − 1. PitchBook quotes AUM growth this way.","source":"PitchBook 2024 Annual Global Private Debt Report; standard formula"},
{"term":"calendar-quarter alignment","kind":"metric","side":"both","popup":"How June and May filers are placed beside December filers: each column is the calendar quarter containing the period end. Read a stacked quarter as 'the quarter each company's period ended in', never as a common ninety days.","source":"This site's own alignment rule","aliases":["calendar quarter","aligned fiscal year"]},
{"term":"capex","expansion":"capital expenditure (tagged)","kind":"metric","side":"both","popup":"Cash paid in the period for property and equipment, from the investing section of the cash-flow statement. Not the company's quoted capex, which may add finance leases or net out incentives.","source":"us-gaap taxonomy elements PaymentsToAcquirePropertyPlantAndEquipment and PaymentsToAcquireProductiveAssets (xbrl.fasb.org); each filer's cash-flow statement","aliases":["capital expenditure","capex (tagged)","cash capex"]},
{"term":"capex run-rate","kind":"metric","side":"both","popup":"The last four quarters of tagged capex added together: the pace the balance sheet must fund over a year at the current tempo. Never the latest quarter times four.","source":"Standard trailing-twelve-month construction on the tagged capex line; this site's own rule","aliases":["run-rate capex"]},
{"term":"capex to depreciation","kind":"metric","side":"both","popup":"Capex divided by depreciation and amortization: how much faster the asset base grows than it is consumed. Near 1.0 is maintenance; well above it is a build-out. A useful-life change moves the denominator without any change in spending.","source":"This site's own ratio catalog (capex ÷ depreciation and amortization); us-gaap taxonomy elements Depreciation and DepreciationDepletionAndAmortization","aliases":["capex/depreciation"]},
{"term":"capex to operating cash flow","kind":"metric","side":"both","popup":"Capex divided by operating cash flow: the share of operating cash the build consumes. Above 1.0 the build is financed from the balance sheet or the market, not from operations.","source":"us-gaap taxonomy element NetCashProvidedByUsedInOperatingActivities; this site's own ratio","aliases":["capex/CFO","capex to CFO"]},
{"term":"Capital overhang","kind":"metric","side":"market","popup":"PitchBook's older name for dry powder, usually shown by vintage year so you can see how old the uncalled money is.","source":"PitchBook Q2 2020 Private Fund Strategies Report; PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025) ('undrawn commitments')"},
{"term":"capital-gains incentive fee","kind":"metric","side":"lender","popup":"The manager's share of realized gains, net of all realized and unrealized losses, settled once a year. It is accrued as marks move and reversed when they fall, so it is shown apart from the cash fee load.","source":"BXSL 10-Q 2026-06-30"},
{"term":"capitalized interest","kind":"metric","side":"both","popup":"Interest on borrowings during construction that is added to the asset's cost instead of being expensed. It lowers reported interest expense while cash interest is unchanged, so the coverage ratio adds it back.","source":"us-gaap taxonomy elements InterestCostsCapitalized and InterestCostsCapitalizedAdjustment (ASC 835-20)","aliases":["interest capitalized"]},
{"term":"Carry","expansion":"Interest return","kind":"metric","side":"market","popup":"The income a loan earns just from its coupon, as opposed to gains or losses from price moves. For floating-rate loans, carry rises and falls with the base rate.","source":"PitchBook 2024 Annual Global Private Debt Report; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figure 95)"},
{"term":"catch-up","kind":"metric","side":"lender","popup":"Once income clears the hurdle, the manager takes 100% of the next slice until it has received its full percentage of everything. BXSL's catch-up runs from 1.5% to 1.82% a quarter.","source":"BXSL 10-Q 2026-06-30"},
{"term":"CCC","kind":"acronym","side":"market","popup":"The bottom of the rating scale before default. CCC borrowers depend on good conditions to keep paying, so their spreads swing hardest.","source":"ICE definition via FRED Notes for BAMLH0A3HYC (fetched 2026-09-11); rating-scale mapping is standard"},
{"term":"Charge-off","kind":"metric","side":"market","popup":"A loan the bank has given up on and removed from its books as a loss, net of anything later recovered.","source":"FRED Notes for CORBLACBS (fetched 2026-09-11)"},
{"term":"CLO","expansion":"Collateralized loan obligation","kind":"instrument","side":"market","popup":"Collateralized loan obligation: a fund that buys hundreds of leveraged loans and pays for them by selling rated bonds in layers. CLOs are the biggest buyers of syndicated loans.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets; LCD US Private Credit Monitor, August 2026, slide 37"},
{"term":"CLO financing","expansion":"collateralized loan obligation financing","kind":"instrument","side":"lender","popup":"The BDC packages its own loans into a securitization and sells rated notes against them, keeping the equity. Cheap, long-dated, secured funding that still counts toward asset coverage.","source":"BXSL 10-Q 2026-06-30; LCD US Private Credit Monitor, August 2026, slide 37"},
{"term":"Club deal","kind":"market","side":"market","popup":"A loan made by a small group of direct lenders, typically one to five, who each hold their piece to maturity instead of selling it on.","source":"LCD US Private Credit Monitor, August 2026, slide 43; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"Committed capital","kind":"metric","side":"market","popup":"The total investors have pledged to a fund, called down over time. Fund size is measured by it, and management fees are usually charged on it.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025)"},
{"term":"companyfacts","kind":"series-id","side":"lender","popup":"The SEC API that returns every tagged fact one company has ever filed, in one JSON file (data.sec.gov/api/xbrl/companyfacts/CIK##########.json). The site's per-BDC history comes from it.","source":"SEC EDGAR APIs page (sec.gov/search-filings/edgar-application-programming-interfaces)"},
{"term":"composite","kind":"metric","side":"lender","popup":"The site's own private credit index: the top 30 BDCs aggregated, weighted by the cost of their third-party loans, with n stated on every figure.","source":"This site's own method for the Lenders view composite"},
{"term":"Constant maturity","kind":"metric","side":"market","popup":"A Treasury yield read off the fitted yield curve at an exact maturity, such as ten years, rather than from one specific bond.","source":"FRED series titles and Notes for DGS10, DGS2, T10Y2Y, BAA10Y (fetched 2026-09-11)"},
{"term":"contract-backed and take-or-pay","kind":"instrument","side":"both","popup":"A customer contract that obliges payment whether or not the capacity is used, pledged to lenders. It is why a speculative-grade borrower can carry an investment-grade project loan. Backlog is revenue, not cash.","source":"The filer's revenue and commitments notes as printed; this site's own reading rule","aliases":["take-or-pay","contract-backed"]},
{"term":"contractual vs amended PIK","kind":"instrument","side":"lender","popup":"Contractual PIK was in the loan from day one, a feature of the deal. Amended PIK was switched on later to relieve a struggling borrower, a symptom. Filings rarely say which, so the site shows the total.","source":"The BDC's own 10-Q PIK disclosure; PitchBook 2023 Annual Global Private Debt Report for the two-track default frame; this site's reading note"},
{"term":"controlled affiliate","kind":"regulation","side":"lender","popup":"A portfolio company the BDC controls, presumed when it owns more than 25% of the voting stock. Income and marks are reported separately for these, and the site keeps them out of the loan statistics.","source":"15 U.S.C. §80a-2(a)(9) (law.cornell.edu); BXSL 10-Q 2026-06-30"},
{"term":"CORBLACBS","expansion":"Net charge-off rate on business loans, all commercial banks","kind":"series-id","side":"market","popup":"Share of bank business loans written off as lost, after any recoveries. The loss that finally lands, months after the delinquency shows up.","source":"FRED series page https://fred.stlouisfed.org/series/CORBLACBS, Notes block, fetched 2026-09-11"},
{"term":"core NII","kind":"metric","side":"lender","popup":"A company-defined version of NII that strips out items the manager calls one-off (for ARCC, 'Core EPS'). Not GAAP, not computed here; shown only where the filing states it.","source":"The BDC's own earnings release or 10-Q, where a core or adjusted NII is disclosed; this site's disclosed-only rule"},
{"term":"cost of debt","kind":"metric","side":"lender","popup":"What the BDC pays on its own borrowings, as a weighted average rate. The other half of its margin: portfolio yield minus cost of debt is what leverage adds.","source":"us-gaap taxonomy element DebtWeightedAverageInterestRate, tagged by ARCC and FSK on SEC EDGAR companyfacts (checked 2026-09-10); otherwise the 10-Q debt note"},
{"term":"Cov-lite","expansion":"Covenant-lite","kind":"instrument","side":"market","popup":"A loan with no financial maintenance covenant, so lenders cannot step in when performance slips. Most syndicated loans are cov-lite; almost no private loans are.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets","aliases":["covenant-lite"]},
{"term":"covenant headroom","kind":"metric","side":"lender","popup":"How far a company is from the next leverage band, in turns of EBITDA and in the earnings drop that would get it there. Labeled synthetic: real covenants live in the credit agreement, which the site cannot see.","source":"This site's own construction on the S&P financial-risk bands and the 6.0x leveraged-lending line"},
{"term":"Credit spread","kind":"metric","side":"market","popup":"The extra yield on risky debt over a risk-free rate. Wider spreads mean investors want more pay for the risk; tighter spreads mean they are relaxed.","source":"PitchBook Q3 2026 Quantitative Perspectives: US Market Insights"},
{"term":"cushion","expansion":"statutory cushion","kind":"metric","side":"lender","popup":"How far the BDC sits above its legal leverage line: coverage ÷ 150% − 1. BXSL at 178% has an 18.7% cushion. Under 15% is the site's flag.","source":"15 U.S.C. §80a-18(a)(1)(B) (law.cornell.edu); BXSL 10-Q 2026-06-30 (178.0%)"},
{"term":"customer prepayments","kind":"metric","side":"both","popup":"Cash received from customers before the capacity is delivered. A funding channel with no coupon, provided by the customer's own balance sheet, that sits inside operating cash flow and lowers capex-to-CFO.","source":"us-gaap taxonomy element IncreaseDecreaseInDeferredRevenue; Oracle's 8-K exhibit 99.1 reconciliation as printed","aliases":["customer prepayment","prepayments"]},
{"term":"debt-to-equity gross and net","kind":"metric","side":"lender","popup":"Gross: total debt ÷ net assets. Net: (debt − cash) ÷ net assets. A 150% asset-coverage BDC can run to about 2.0× gross; most sit near 1.0-1.2×.","source":"SEC EDGAR companyfacts for ARCC, BXSL, MAIN, OBDC, FSK and GBDC (checked 2026-09-10)"},
{"term":"debt/EBITDA","kind":"metric","side":"lender","popup":"Total debt divided by trailing-twelve-month EBITDA: how many years of cash earnings it would take to repay the debt. S&P calls under 1.5x minimal and over 5x highly leveraged.","source":"S&P 2009 corporate ratings criteria, financial-risk matrix Table 2 (efis.psc.mo.gov/Document/Display/44676); MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets","aliases":["debt to EBITDA","total leverage"]},
{"term":"Default rate","kind":"metric","side":"market","popup":"The share of loans in an index that defaulted over the past twelve months, by number of borrowers or by dollars outstanding.","source":"PitchBook 2023 Annual Global Private Debt Report; PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026"},
{"term":"delayed-draw","expansion":"delayed-draw term loan","kind":"instrument","side":"lender","popup":"A term loan the borrower can draw in pieces up to a deadline, usually to fund acquisitions. Until drawn it is an unfunded commitment that earns no interest.","source":"BXSL 10-Q 2026-06-30","aliases":["delayed-draw term loan","delayed draw term loan","DDTL","delayed-draw term loans"]},
{"term":"Delinquency","kind":"metric","side":"market","popup":"A loan that is behind on a scheduled payment but not yet written off. The first visible sign of borrower stress in bank data.","source":"FRED series title for DRBLACBS"},
{"term":"DGS10","expansion":"10-year Treasury constant-maturity yield","kind":"series-id","side":"market","popup":"The yield on a 10-year US Treasury. The risk-free anchor that every credit spread on this page is measured against.","source":"FRED series page https://fred.stlouisfed.org/series/DGS10, Notes block, fetched 2026-09-11"},
{"term":"DGS2","expansion":"2-year Treasury constant-maturity yield","kind":"series-id","side":"market","popup":"The yield on a 2-year US Treasury. It tracks where the market thinks the Fed's policy rate is heading over the next two years.","source":"FRED series page https://fred.stlouisfed.org/series/DGS2, Notes block, fetched 2026-09-11"},
{"term":"differencing","kind":"metric","side":"lender","popup":"Turning a year-to-date figure into a single quarter by subtracting the previous year-to-date figure. Only done inside one fiscal year and only when the earlier quarters exist.","source":"This site's own construction: the derived fourth quarter and the year-to-date fill, applied inside one fiscal year only"},
{"term":"Direct lending","kind":"market","side":"market","popup":"Loans made straight to a company by a non-bank lender, without a bank arranging or syndicating them. Usually senior, secured, floating rate and held to maturity.","source":"LCD US Private Credit Monitor, August 2026, slide 43 methodology; PitchBook 2024 Annual Global Private Debt Report ('Fund type definitions' and the AUM figure)"},
{"term":"dispersion","kind":"metric","side":"lender","popup":"The spread of a metric across the 30 BDCs: min, P25, median, P75, max. It shows where one BDC sits in the pack, which matters more than the number alone.","source":"This site's own method for the Lenders view composite"},
{"term":"Distressed debt","kind":"market","side":"market","popup":"Buying the loans or bonds of a company already in trouble, at a deep discount, in the hope of a profit through a restructuring.","source":"PitchBook 2024 Annual Global Private Debt Report"},
{"term":"Distressed exchange","kind":"market","side":"market","popup":"A troubled borrower swaps its debt for new debt worth less, or buys it back cheaply, to avoid bankruptcy. Lenders take a haircut now to recover more than a court process would give.","source":"PitchBook 2023 Annual Global Private Debt Report"},
{"term":"Distressed ratio","kind":"metric","side":"market","popup":"The share of performing loans priced below 80 cents on the dollar. It is an early-warning gauge: loans get cheap before they default.","source":"PitchBook 2023 Annual Global Private Debt Report"},
{"term":"distressed share","kind":"metric","side":"lender","popup":"The share of the loan book marked below 80 cents on the dollar: cost of third-party debt with FV/cost under 0.80 ÷ cost of third-party debt. The private analogue of the leveraged-loan 'under-80' ratio.","source":"This site's own per-loan rule on the parsed schedule of investments; PitchBook 2023 Annual Global Private Debt Report for the loan-index reference figures"},
{"term":"distributable NII","kind":"metric","side":"lender","popup":"MAIN's name for its adjusted NII: what it considers available to pay out ($1.04 per share, Q2 2026). Company-defined, shown only where stated.","source":"The BDC's own earnings release (MAIN Q2 2026: 'distributable NII' $1.04 per share); this site's disclosed-only rule"},
{"term":"dividend coverage","kind":"metric","side":"lender","popup":"After-tax NII per share ÷ dividend per share. Above 1.0× the dividend is earned; below it, the BDC is paying from reserves, gains or capital. MAIN Q2 2026: 1.24× on the regular dividend, 0.90× on the total.","source":"This site's own ratio on the tagged 10-Q facts (BXSL 10-Q 2026-06-30 for the Q2 2026 figures)"},
{"term":"dividend recapitalization","kind":"market","side":"market","popup":"New debt raised by a company so its owner can pay itself a dividend. Sponsors use it to return cash when exits are slow; for the lender it adds leverage without adding earnings.","source":"PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figures 59-60); LCD US Private Credit Monitor, August 2026, slide 8 (use-of-proceeds categories)","aliases":["dividend recap","dividend recaps","recapitalization"]},
{"term":"dividend yield","kind":"metric","side":"lender","popup":"Trailing twelve months of distributions divided by the share price. For BDCs it runs near ten percent, which is why price and total return diverge so much on chart M8.","source":"Finnhub stock/metric currentDividendYieldTTM (checked 2026-09-10)"},
{"term":"DPI","expansion":"distributions to paid-in capital","kind":"acronym","side":"market","popup":"Cash actually returned to investors divided by the capital they paid in. The realization multiple: the part of a fund's return that is no longer an estimate. Not computed on this site.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Multiples'"},
{"term":"DPRIME","expansion":"Bank prime loan rate","kind":"series-id","side":"market","popup":"The prime rate: the base rate most US banks post for their best business customers. Small-business and revolving loans are often priced off it.","source":"FRED series page https://fred.stlouisfed.org/series/DPRIME, Notes block, fetched 2026-09-11"},
{"term":"drawdown fund","kind":"market","side":"market","popup":"The traditional private fund: investors commit capital, the manager calls it down over a few years, and the fund winds up after about ten. PitchBook's benchmarks and fundraising counts cover only these.","source":"PitchBook Q3 2024 Analyst Note: The Evergreen Evolution; PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025); PitchBook 2024 Annual Global Private Debt Report","aliases":["drawdown funds","closed-end drawdown fund","finite-life fund"]},
{"term":"DRBLACBS","expansion":"Delinquency rate on business loans, all commercial banks","kind":"series-id","side":"market","popup":"Share of bank business loans that are behind on payments. A slow, lagging read on how the bank-lent middle market is coping.","source":"FRED series page https://fred.stlouisfed.org/series/DRBLACBS, Notes block, fetched 2026-09-11"},
{"term":"DRSDCILM","expansion":"SLOOS net stronger demand, C&I, large and middle-market firms","kind":"series-id","side":"market","popup":"Share of banks seeing stronger demand for business loans from big and mid-sized companies, net of those seeing weaker demand. Positive means companies want to borrow more.","source":"FRED series page https://fred.stlouisfed.org/series/DRSDCILM, Notes block, fetched 2026-09-11"},
{"term":"DRTSCILM","expansion":"SLOOS net tightening, C&I, large and middle-market firms","kind":"series-id","side":"market","popup":"Share of banks tightening loan terms for big and mid-sized companies, net of those loosening. Above 20 means banks are pulling back; that is when private lenders win business.","source":"FRED series page https://fred.stlouisfed.org/series/DRTSCILM, Notes block, fetched 2026-09-11"},
{"term":"DRTSCIS","expansion":"SLOOS net tightening, C&I, small firms","kind":"series-id","side":"market","popup":"Same survey, but for loans to small companies. Small firms feel a bank pullback first, so this often leads the large-firm reading.","source":"FRED series page https://fred.stlouisfed.org/series/DRTSCIS, Notes block, fetched 2026-09-11"},
{"term":"Dry powder","kind":"metric","side":"market","popup":"Money investors have committed to funds that has not yet been lent out. It is the industry's spending power, and a lot of it means pressure to do deals.","source":"PitchBook 2024 Annual Global Private Debt Report; PitchBook Benchmarks, All Benchmarks table (data as of 2025 Q4)","aliases":["dry-powder"]},
{"term":"DSCR","expansion":"debt service coverage ratio","kind":"acronym","side":"both","popup":"Cash available for debt service divided by scheduled principal and interest. The covenant project lenders test on a delayed-draw facility. Definitions differ per facility, so the site prints the printed figure and never computes one.","source":"The facility covenant or the rating agency's base case as printed; standard project-finance definition","aliases":["debt service coverage ratio","debt service coverage"]},
{"term":"Dual-track default rate","expansion":"DTDR","kind":"metric","side":"market","popup":"LCD's broader default measure: missed payments and bankruptcies plus distressed exchanges. It catches the quiet restructurings the traditional rate misses.","source":"PitchBook 2023 Annual Global Private Debt Report"},
{"term":"EBITDA","expansion":"earnings before interest, taxes, depreciation and amortization","kind":"acronym","side":"both","popup":"Operating profit with depreciation and amortization added back: the rough cash earnings lenders size debt against. Every leverage and coverage ratio in credit uses it, and add-backs can inflate it.","source":"This site's own ratio catalog (EBITDA and debt/EBITDA); BXSL 10-Q 2026-06-30; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets, structural protections section"},
{"term":"Effective yield","kind":"metric","side":"market","popup":"The total yield a bond index pays, Treasury rate plus spread, weighted by market value. For high yield it is the going rate on a liquid alternative to a private loan.","source":"ICE definition via FRED Notes for BAMLH0A0HYM2EY (fetched 2026-09-11)"},
{"term":"EURIBOR","expansion":"Euro Interbank Offered Rate","kind":"acronym","side":"both","popup":"The euro area's interbank term rate, published by EMMI. Euro loans in a BDC book reset off EURIBOR, so a spread over base means over EURIBOR for them, not over SOFR.","source":"EMMI EURIBOR page (emmi-benchmarks.eu/benchmarks/euribor); BXSL 10-Q 2026-06-30 schedule footnote 2","aliases":["Euribor"]},
{"term":"EV","expansion":"enterprise value","kind":"acronym","side":"lender","popup":"What the whole business is worth to all its funders: equity value plus net debt. Lenders compare their loan with it (loan-to-value) because it is the pot that repays them if the company is sold.","source":"BXSL 10-Q 2026-06-30 (valuation note); this site's own enterprise-value bridge"},
{"term":"evergreen vehicle","kind":"market","side":"market","popup":"A fund with no end date: investors can buy in at intervals and redeem within limits, and capital is recycled into new loans instead of returned. Non-traded BDCs and interval funds are the private credit versions.","source":"PitchBook Q3 2024 Analyst Note: The Evergreen Evolution, 'A note on terminology'; PitchBook 2024 Annual Global Private Debt Report","aliases":["evergreen","evergreen fund","evergreen funds","perpetual capital","semi-liquid","perpetual-life"]},
{"term":"excise tax","kind":"regulation","side":"lender","popup":"A 4% federal tax a BDC pays on income it keeps instead of distributing on time. Paying it is a choice: keep spillover and pay 4%, or pay everything out.","source":"BXSL 10-Q 2026-06-30"},
{"term":"exemptive relief","kind":"regulation","side":"lender","popup":"An SEC order that lets a fund do something the 1940 Act would otherwise forbid: co-invest alongside sister funds, or leave SBA debentures out of the leverage test.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets (the SEC-order discussion); the filer's own 10-Q sentence on SBA debentures"},
{"term":"expense ratio tags","kind":"series-id","side":"lender","popup":"The XBRL family InvestmentCompanyExpenseRatio..., which filers tag inconsistently (year-to-date, with or without incentive fees, sometimes annualized). The site uses them only as a cross-check.","source":"us-gaap investment-company taxonomy elements InvestmentCompanyExpenseRatioIncludingIncentiveFee, InvestmentCompanyExpenseRatioBeforeIncentiveAllocation and InvestmentCompanyExpenseRatio; SEC XBRL frames, CY2026Q2, for the coverage counts"},
{"term":"externally managed","kind":"regulation","side":"lender","popup":"The BDC has no employees; an affiliated adviser runs it for a management fee plus incentive fees under an advisory agreement. Most listed BDCs, including ARCC and BXSL.","source":"BXSL 10-Q 2026-06-30"},
{"term":"fair value","kind":"metric","side":"lender","popup":"The price a loan would fetch in an orderly sale today, as estimated by the BDC's board and valuation firms. Most private loans have no quote, so fair value is a model, not a trade.","source":"BXSL 10-Q 2026-06-30"},
{"term":"FCCR","expansion":"fixed-charge coverage ratio","kind":"acronym","side":"lender","popup":"Fixed-charge coverage ratio: (EBITDA minus capex minus cash taxes) over (cash interest plus mandatory amortization). A second maintenance covenant in about one in five private loans, beside the total-leverage test (Proskauer, 2021).","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets (structural protections section); standard loan-covenant definition"},
{"term":"FFO/debt","expansion":"funds from operations to debt","kind":"metric","side":"lender","popup":"S&P's main cash-flow leverage ratio: funds from operations as a percentage of debt. Over 60% is minimal risk, under 12% highly leveraged.","source":"S&P 2009 corporate ratings criteria, financial-risk matrix Table 2 (efis.psc.mo.gov/Document/Display/44676)"},
{"term":"finance lease vs operating lease","kind":"regulation","side":"both","popup":"A finance lease transfers most of the asset's economics to the tenant and is presented like debt; an operating lease is a right of use with rent expense. Moving new leases to operating cuts reported capex, not the commitment.","source":"ASC 842 (Leases); us-gaap taxonomy elements FinanceLeaseLiability, OperatingLeaseLiability and RightOfUseAssetObtainedInExchangeForFinanceLeaseLiability; the filer's leases note","aliases":["finance lease","operating lease","finance leases","operating leases"]},
{"term":"Financial stress index","kind":"metric","side":"market","popup":"A composite that turns many rates and spreads into one number for how stressed markets are. The St. Louis Fed's version is zero on average; above zero is more stress than usual.","source":"FRED Notes for STLFSI4 and NFCI (fetched 2026-09-11)"},
{"term":"First lien","expansion":"Senior secured first lien","kind":"instrument","side":"market","popup":"The most senior secured loan: first claim on the borrower's assets if things go wrong. Lowest risk in the capital stack, so lowest spread.","source":"LCD US Private Credit Monitor, August 2026, slide 14 footnote and slide 29 chartHeading"},
{"term":"first-lien last-out","kind":"instrument","side":"lender","popup":"A slice of a first-lien loan that agrees to be repaid after the 'first-out' slice. Same collateral, lower place in the queue, higher rate. The site keeps it in first lien but labels it.","source":"BDC schedules of investments, where the tranche is labeled 'first lien, last-out'; this site's lien-mix labels"},
{"term":"fiscal year end","kind":"metric","side":"lender","popup":"The month a filer closes its books. Nine of the 50 BDCs are not December filers (GBDC, OCSL, PFLT, PNNT, GLAD Sept 30; CSWC, GAIN Mar 31; PSEC Jun 30; SAR Feb 28), so their quarters do not line up with calendar frames.","source":"SEC EDGAR submissions JSON (data.sec.gov/submissions/CIK##########.json), fiscalYearEnd field, checked 2026-09-10"},
{"term":"Fitch","expansion":"Fitch Ratings","kind":"market","side":"market","popup":"One of the three big rating agencies, on the AAA-to-D scale shared with S&P. Its private credit default count is drawn here as its own series, never averaged with the others.","source":"FRED Notes for BAMLH0A0HYM2 (ratings averaged across Moody's, S&P and Fitch), fetched 2026-09-11","aliases":["Fitch Ratings"]},
{"term":"floating-rate share","kind":"metric","side":"lender","popup":"The part of the debt book whose interest resets with a base rate like SOFR. Near 100% for most BDCs (BXSL 99.3%), so falling rates cut income unless floors bite.","source":"BXSL 10-Q 2026-06-30"},
{"term":"Floor","kind":"instrument","side":"market","popup":"A minimum level for the base rate written into a loan. If SOFR falls below the floor, the borrower still pays the floor plus spread, so lenders keep income when rates drop.","source":"Usage: PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026 (the 'Floor (bps)' column). Definition is standard."},
{"term":"frames","kind":"series-id","side":"lender","popup":"The SEC API that returns one fact per filer for one tag and one calendar period (e.g. NetAssetValuePerShare for CY2026Q2I). It is how the site finds all 50 BDCs at once and counts who tags what.","source":"SEC EDGAR APIs page (sec.gov/search-filings/edgar-application-programming-interfaces)"},
{"term":"fulcrum security","kind":"instrument","side":"market","popup":"The most junior claim that still gets paid something in a restructuring, so it ends up owning the company. Distressed funds buy it at a discount to take control.","source":"PitchBook 2024 Annual Global Private Debt Report, 'Fund type definitions'","aliases":["fulcrum"]},
{"term":"funding gap","kind":"metric","side":"both","popup":"Capex plus buybacks, dividends and debt repaid, minus operating cash flow: the cash a company had to raise or draw down in the period. Positive means the market or the cash pile paid.","source":"This site's own arithmetic on the tagged cash-flow lines (capex, buybacks, dividends, debt repaid, operating cash flow)"},
{"term":"Fundraising","kind":"metric","side":"market","popup":"New money committed to private debt funds in a period, counted when a fund closes. The fundraising tiles use PitchBook's fundraising-report series.","source":"PitchBook 2024 Annual Global Private Debt Report; LCD US Private Credit Monitor, August 2026, slide 36"},
{"term":"FV/cost","expansion":"fair value to amortized cost","kind":"metric","side":"lender","popup":"Fair value divided by amortized cost. ARCC 0.989 and BXSL 0.964 at Jun 30 2026; MAIN 1.155 because of its equity positions.","source":"This site's own ratio: InvestmentOwnedAtFairValue ÷ InvestmentOwnedAtCost per holding from the schedule of investments, and in total from SEC EDGAR companyfacts"},
{"term":"GP","expansion":"general partner","kind":"acronym","side":"market","popup":"The manager of a private fund: it raises the money, picks the loans, controls when capital is called and returned, and earns the management fee and carried interest.","source":"PitchBook Q3 2024 Analyst Note: The Evergreen Evolution; PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Fund-level cash flow and performance metrics'","aliases":["general partner"]},
{"term":"gross debt (principal)","kind":"metric","side":"both","popup":"Total principal of borrowings outstanding: the number the maturity ladder has to refinance. Face value, not carrying value, which can sit below face after an exchange premium.","source":"us-gaap taxonomy elements DebtInstrumentCarryingAmount and LongTermDebt; the filer's debt note","aliases":["gross debt","debt principal","total principal"]},
{"term":"guidance vs outturn","kind":"metric","side":"both","popup":"What management said it would spend against what the cash-flow statement shows. A staircase that only rises is a company that kept underestimating; a definition change is labeled, never read as a cut.","source":"The company's guidance as printed in its earnings release or call transcript; this site's own comparison rule","aliases":["outturn"]},
{"term":"H.15","expansion":"H.15 release","kind":"acronym","side":"market","popup":"The Fed's daily release of selected interest rates: Treasury yields, the prime rate and other benchmarks.","source":"FRED Notes 'Release' field for DGS10, DGS2 and DPRIME (fetched 2026-09-11)"},
{"term":"H.8","expansion":"H.8 release","kind":"acronym","side":"market","popup":"The Fed's weekly statistical release on what US commercial banks hold: loans by type, securities and total bank credit.","source":"FRED Notes 'Release' field for BUSLOANS, LNFACBW027SBOG and TOTBKCR (fetched 2026-09-11)"},
{"term":"harmonic mean","kind":"metric","side":"lender","popup":"An average that tames big outliers: n ÷ Σ(1/x). Used to aggregate peer multiples, because a plain mean of ratios is dragged up by one extreme value.","source":"Liu, Nissim and Thomas, 'Equity Valuation Using Multiples' (2002), equation 3; this site's own peer aggregate"},
{"term":"hurdle","expansion":"hurdle rate","kind":"metric","side":"lender","popup":"The minimum return on net assets the BDC must earn before the manager gets an incentive fee. BXSL: 1.5% a quarter (6.0% a year).","source":"BXSL 10-Q 2026-06-30"},
{"term":"HY","expansion":"High yield","kind":"acronym","side":"market","popup":"High yield, or junk: bonds rated below investment grade (BB+ and lower). They pay more because the issuers are more likely to default.","source":"ICE definition via FRED Notes for BAMLH0A0HYM2 (fetched 2026-09-11)"},
{"term":"ICE BofA","expansion":"ICE BofA bond indices (Intercontinental Exchange, formerly Bank of America Merrill Lynch)","kind":"market","side":"market","popup":"The bond index family behind the six spread and yield tiles. FRED carries the index-level option-adjusted spreads and effective yields, but only three years of history since April 2026.","source":"FRED series pages for BAMLH0A0HYM2, BAMLC0A0CM and BAMLH0A0HYM2EY, Notes block (fetched 2026-09-11)","aliases":["ICE BofA US High Yield Index","ICE BofA US Corporate Index"]},
{"term":"IG","expansion":"Investment grade","kind":"acronym","side":"market","popup":"Investment grade: bonds rated BBB- or better. The safest corporate debt, and the cheapest for issuers.","source":"ICE definition via FRED Notes for BAMLC0A0CM (fetched 2026-09-11)"},
{"term":"income incentive fee","kind":"metric","side":"lender","popup":"The manager's share of NII above a hurdle (BXSL: 17.5%; the fee card records each filer's rate). It is charged on accrued income, including PIK not yet received, and can be paid even when NAV is falling unless a cap or lookback applies.","source":"BXSL 10-Q 2026-06-30"},
{"term":"incurrence covenant","kind":"instrument","side":"market","popup":"A covenant tested only when the borrower acts: takes on more debt, pays a dividend, sells assets. It cannot trip on its own, so a cov-lite loan with only incurrence tests gives lenders no early seat at the table.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets, structural protections section; the incurrence/maintenance distinction is standard loan-documentation vocabulary","aliases":["incurrence covenants","incurrence test"]},
{"term":"Infrastructure debt","kind":"market","side":"market","popup":"Long-dated lending to infrastructure projects, both new builds and existing assets. Terms can run thirty years or more because the assets last that long. One of PitchBook's nine private debt fund types.","source":"PitchBook 2024 Annual Global Private Debt Report, 'Fund type definitions'"},
{"term":"Institutional loan","kind":"market","side":"market","popup":"The part of the syndicated loan market bought by funds and CLOs rather than banks: floating-rate term loans, mostly cov-lite, non-amortizing, and tradeable.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"interest coverage","kind":"metric","side":"lender","popup":"EBIT or EBITDA divided by interest expense: how many times earnings cover the interest bill. Below about 1x a company is not earning its interest. No document in the folder states a floor, so none is drawn.","source":"This site's own ratio catalog (EBIT, EBITDA and NOPAT over interest expense)","aliases":["interest cover"]},
{"term":"interest-rate sensitivity","kind":"metric","side":"lender","popup":"How much NII moves if base rates shift 100 bps, from the filer's own Item 3 table. BXSL: +$132.6M income, −$23.8M expense, +$108.8M net per year for a 100 bp rise.","source":"BXSL 10-Q 2026-06-30"},
{"term":"internally managed","kind":"regulation","side":"lender","popup":"The BDC employs its own staff and pays salaries instead of paying an outside adviser. No management or incentive fee line: MAIN, HTGC, TRIN and CSWC.","source":"The BDC's own 10-K description of its management structure; this site's fee card"},
{"term":"InvestmentIdentifierAxis","kind":"series-id","side":"lender","popup":"The XBRL axis that names each individual holding. Facts hanging off it (cost, fair value, spread, rate, principal, unfunded amount) give loan-level detail for every BDC.","source":"us-gaap taxonomy axis InvestmentIdentifierAxis; the BXSL 10-Q XBRL instance (accession 0001736035-26-000016)"},
{"term":"IRR","expansion":"internal rate of return","kind":"acronym","side":"market","popup":"The annual return that makes a fund's capital calls and distributions net to zero. It rewards getting money back early. Not computed on this site; benchmark values are drawn as dated points only.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Internal rate of return'","aliases":["internal rate of return"]},
{"term":"joint venture","kind":"instrument","side":"lender","popup":"A lending partnership the BDC co-owns with another investor. The BDC books its share as one investment, and the venture borrows on its own, so its yield is levered.","source":"ARCC 10-Q 2026-06-30 (the SDLP disclosure); SEC BDC data set, July 2026 soi.tsv (joint-venture subtotal rows)"},
{"term":"joint-venture financing","kind":"instrument","side":"both","popup":"A data-center campus owned mostly by a fund, with the hyperscaler as minority owner and tenant. The capex moves off the hyperscaler's balance sheet into a bond the fund's vehicle sells; the tenant's exposure is a lease plus a guarantee.","source":"The filer's commitments, guarantees and leases notes as printed; this site's own ledger method","aliases":["JV financing","joint venture financing"]},
{"term":"KBRA","expansion":"Kroll Bond Rating Agency","kind":"acronym","side":"market","popup":"A US credit rating agency whose private credit default figures this site draws as a separate series with its own definition, never averaged with Proskauer's, Fitch's or Moody's.","source":"KBRA (kbra.com), the agency's own site; this site's own rule not to build a market-wide private credit default rate","aliases":["Kroll Bond Rating Agency"]},
{"term":"Last-out","expansion":"First-out / last-out","kind":"instrument","side":"market","popup":"Inside a unitranche, the slice that gets paid last. Lenders privately split one loan into first-out and last-out pieces; the last-out piece earns more of the blended rate.","source":"Standard definition; not defined in the study material or on a fetched page; unitranche context from MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"LBO","expansion":"Leveraged buyout","kind":"market","side":"market","popup":"Leveraged buyout: a private equity firm buys a company using mostly borrowed money. LBO loans are the core product of both direct lending and the syndicated market.","source":"LCD US Private Credit Monitor, August 2026, slides 9-10, 13-19, 21-22 titles; PitchBook 2024 Annual Global Private Debt Report ('Often used in LBO transactions')"},
{"term":"LCD","expansion":"PitchBook LCD (Leveraged Commentary & Data)","kind":"acronym","side":"market","popup":"PitchBook's loan-market news and data unit. Its monthly US private credit monitor and daily leveraged loan playbook supply the deal-flow, spread, BDC-portfolio and takeout series here.","source":"LCD US Private Credit Monitor, August 2026 (slide 43 methodology); PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026","aliases":["PitchBook LCD"]},
{"term":"leases not yet commenced","kind":"regulation","side":"both","popup":"Signed leases, mostly data centers, whose term has not started. Undiscounted future payments over terms up to twenty years; not debt and not on the balance sheet, but the forward commitment to the landlords.","source":"ASC 842 leases-note disclosure of leases not yet commenced; us-gaap taxonomy element UnrecordedUnconditionalPurchaseObligationBalanceSheetAmount; the filer's leases note","aliases":["uncommenced leases","uncommenced lease","leases that have not yet commenced"]},
{"term":"Leveraged loan","kind":"market","side":"market","popup":"A loan to a company that already carries a lot of debt or is rated below investment grade. Floating rate and usually secured. Both BSL and direct loans are leveraged loans.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets. General definition is standard."},
{"term":"Leveraged loan index","expansion":"Morningstar LSTA US Leveraged Loan Index","kind":"market","side":"market","popup":"The Morningstar LSTA US Leveraged Loan Index, which tracks prices and returns of institutional loans. PitchBook uses it as the public stand-in for private debt returns.","source":"PitchBook 2024 Annual Global Private Debt Report; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figures 94-95); PitchBook 2023 Annual Global Private Debt Report","aliases":["loan index"]},
{"term":"leveraged-lending guidance","kind":"regulation","side":"lender","popup":"The 2013 US bank regulators' guidance that treated more than 6x debt/EBITDA as a red flag for bank underwriting. Private lenders are not bound by it, which is why they can attach higher.","source":"Interagency Guidance on Leveraged Lending (OCC, Federal Reserve, FDIC, March 2013); MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets, footnote 27"},
{"term":"liability ladder","kind":"metric","side":"lender","popup":"How the BDC itself is funded: unsecured notes versus secured lines (SPVs, CLOs, revolver), what falls due in the next year, and the undrawn revolver.","source":"BXSL 10-Q 2026-06-30"},
{"term":"liquidity cover","kind":"metric","side":"lender","popup":"(Cash + undrawn revolver) ÷ unfunded commitments. Above 1.0× the BDC can fund everything it has promised without raising money.","source":"us-gaap taxonomy element LineOfCreditFacilityRemainingBorrowingCapacity; the BDC's 10-Q liquidity paragraph; this site's own ratio"},
{"term":"liquidity runway","kind":"metric","side":"lender","popup":"(Cash + undrawn revolver + last-twelve-month free cash flow) ÷ (debt due in 12 months + lease payments). Under 1.0× the company must refinance to get through the year.","source":"SEC XBRL frames, CY2025Q4I, across the 130 covered companies (LineOfCreditFacilityRemainingBorrowingCapacity, LesseeOperatingLeaseLiabilityPaymentsDue, InterestPaidNet); this site's own construction"},
{"term":"LL100","expansion":"Morningstar LSTA US Leveraged Loan 100 Index","kind":"market","side":"market","popup":"The Morningstar LSTA US Leveraged Loan 100, an index of the 100 largest loans. Quoted as an average price: 100 is par, so 97.62 means loans trade at a small discount.","source":"PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026. Index composition is a standard definition."},
{"term":"LNFACBW027SBOG","expansion":"H.8 loans to nondepository financial institutions","kind":"series-id","side":"market","popup":"Bank loans to non-bank lenders such as private credit funds and BDCs. It shows how much of private credit is itself funded by the banks.","source":"FRED series page https://fred.stlouisfed.org/series/LNFACBW027SBOG, Notes block, fetched 2026-09-11; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figure 101)"},
{"term":"loan-to-value","expansion":"LTV","kind":"metric","side":"lender","popup":"Debt through a lender's tranche ÷ the borrower's enterprise value. A 50% LTV means the company's value would have to halve before the lender loses. BXSL's average: 51.9%.","source":"BXSL 10-Q 2026-06-30 ('Average loan-to-value (LTV)' in the portfolio table)"},
{"term":"LP","expansion":"limited partner","kind":"acronym","side":"market","popup":"An investor in a private fund, such as a pension plan or insurer. LPs commit capital, the manager calls it over time, and their liability is limited to what they committed.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Internal rate of return'; PitchBook Fund Overview workbook, sources of capital sheet (downloaded 2026-09-10)","aliases":["limited partner","limited partners"]},
{"term":"LTM","expansion":"last twelve months","kind":"acronym","side":"lender","popup":"The most recent four quarters added together. Used for EBITDA, free cash flow and interest so that ratios are not distorted by one seasonal quarter.","source":"Standard definition; this site's own statements feed for the LTM window"},
{"term":"Maintenance covenant","expansion":"Financial maintenance covenant","kind":"instrument","side":"market","popup":"A promise tested every quarter, such as debt under a set multiple of earnings. Breaking it lets lenders get to the table early, before a small problem becomes a default.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets","aliases":["maintenance covenants","financial maintenance covenant"]},
{"term":"management fee","kind":"metric","side":"lender","popup":"The base fee an external manager charges on the BDC's assets, paid whether or not the fund makes money. BXSL: 1.0% a year of gross assets, $35.3M in Q2 2026.","source":"BXSL 10-Q 2026-06-30"},
{"term":"mandatory convertible preferred","kind":"instrument","side":"both","popup":"Preferred shares that convert into common stock at a set date within a price range. Equity for the rating agencies but with a fixed dividend: a way to raise equity-credit capital without a common-stock discount.","source":"us-gaap taxonomy element ProceedsFromIssuanceOfConvertiblePreferredStock; the issuer's prospectus supplement as printed","aliases":["mandatory convertible","mandatory convertible preferred stock"]},
{"term":"mark","kind":"metric","side":"lender","popup":"The manager's fair value on a loan relative to what it cost. Below 1.0 the book is carrying an unrealized loss; a mark well under cost before a loan stops paying is the early warning.","source":"BXSL 10-Q 2026-06-30"},
{"term":"market flex","kind":"market","side":"market","popup":"The arranging bank's right to raise the price or tighten the terms of a syndicated loan if investors will not buy it as first offered. Private lenders commit without it, which is the certainty sponsors pay for.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets, syndication section","aliases":["flex"]},
{"term":"maturity ladder","kind":"metric","side":"both","popup":"Principal due by year. Near-term bars set against cash and undrawn facilities are the refinancing risk; the same picture the BDC maturity wall gives for a loan book.","source":"us-gaap taxonomy elements LongTermDebtMaturitiesRepaymentsOfPrincipalInNextTwelveMonths through AfterYearFive; SEC XBRL frames, CY2025Q4I, across the 130 covered companies"},
{"term":"maturity wall","kind":"metric","side":"lender","popup":"When the BDC's borrowers must repay or refinance, stacked by year. A heavy near-term share in a tight market means extensions and amendments ahead. LCD: the largest BDC share falls in 2031-2033.","source":"LCD US Private Credit Monitor, August 2026, slides 31-32"},
{"term":"megafund","kind":"market","side":"market","popup":"PitchBook's word for the largest funds in a strategy, the top size bucket in its fundraising charts. A few of them can carry a year's fundraising total, so the fund count matters as much as the dollars.","source":"PitchBook 2024 Annual Global Private Debt Report; PitchBook 2023 Annual Global Private Debt Report; PitchBook Q2 2026 Global Private Market Fundraising Report size buckets","aliases":["megafunds"]},
{"term":"Mezzanine","kind":"instrument","side":"market","popup":"Subordinated debt that sits between senior loans and equity, often with warrants or other equity kickers. Higher rate, repaid after the senior lender.","source":"PitchBook 2024 Annual Global Private Debt Report; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"MFA","expansion":"Managed Funds Association","kind":"acronym","side":"market","popup":"The trade body for alternative asset managers. With Proskauer it wrote the paper the Underwriting view leans on for covenant incidence, attachment points and how private credit differs from syndicated loans.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets","aliases":["Managed Funds Association","MFA/Proskauer"]},
{"term":"Middle market","kind":"market","side":"market","popup":"Companies too small for the public bond and syndicated loan markets. The core private-credit borrower, usually unrated and often owned by a private equity sponsor.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets; LCD US Private Credit Monitor, August 2026, slide 43; FRED series title for DRTSCILM"},
{"term":"Middle-market CLO","expansion":"Private credit CLO","kind":"instrument","side":"market","popup":"A CLO that holds directly originated middle-market loans instead of syndicated ones. It is how direct lenders borrow against their own loan books.","source":"LCD US Private Credit Monitor, August 2026, slide 37 title and chartHeading"},
{"term":"Moody's","expansion":"Moody's Ratings","kind":"market","side":"market","popup":"One of the three big rating agencies. Its Baa grade is the lowest investment-grade band, and FRED's BAA10Y is Moody's seasoned Baa corporate yield minus the 10-year Treasury.","source":"FRED series page for BAA10Y (Moody's Seasoned Baa Corporate Bond Yield Relative to Yield on 10-Year Treasury Constant Maturity), fetched 2026-09-11; FRED Notes for BAMLH0A0HYM2 (rating average)","aliases":["Moody’s","Moody's Ratings"]},
{"term":"Morningstar LSTA","expansion":"Morningstar LSTA US Leveraged Loan Index family","kind":"market","side":"market","popup":"The index family that prices the syndicated loan market: the full Leveraged Loan Index and the LL100 of the hundred largest loans. PitchBook uses it as the public stand-in for private debt returns.","source":"PitchBook 2024 Annual Global Private Debt Report; PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026","aliases":["LSTA","Morningstar LSTA US Leveraged Loan Index"]},
{"term":"Multistrategy","expansion":"general-purpose private debt (PitchBook's 'Debt' fund type)","kind":"market","side":"market","popup":"PitchBook's catch-all fund type, labeled 'Debt' on the chart: credit funds with a broad mandate across the capital structure and sub-strategies, often holding public debt as well as private.","source":"PitchBook 2024 Annual Global Private Debt Report, 'Fund type definitions'","aliases":["general debt","Debt (fund type)","multistrategy debt"]},
{"term":"NAV","expansion":"Net asset value","kind":"metric","side":"market","popup":"Net asset value: assets minus liabilities, the book value of a fund or BDC. For a listed BDC, price divided by NAV tells you what the market thinks of the manager's marks.","source":"PitchBook 2024 Annual Global Private Debt Report"},
{"term":"NAV per share","kind":"metric","side":"lender","popup":"Net assets divided by shares outstanding. The number the share price is compared with. ARCC $19.35, BXSL $25.53, MAIN $33.92 at June 30, 2026.","source":"us-gaap taxonomy element NetAssetValuePerShare, as tagged by every listed BDC on SEC EDGAR companyfacts"},
{"term":"NDFI","expansion":"Nondepository financial institutions","kind":"acronym","side":"market","popup":"Nondepository financial institutions: lenders that are not banks, such as private credit funds, BDCs, finance companies and mortgage companies. Banks increasingly lend to them.","source":"FRED series title for LNFACBW027SBOG; PitchBook Q3 2026 Quantitative Perspectives: US Market Insights; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"neocloud","kind":"market","side":"both","popup":"A specialist provider that rents GPU compute to hyperscalers and model developers, building data centers on borrowed money against signed contracts. The section-15 cohort of six, each with its own filing basis.","source":"This site's own label; the filers' SIC codes on the SEC submissions index","aliases":["neoclouds"]},
{"term":"net cash outlay for capex","expansion":"Oracle's company-defined capex measure","kind":"metric","side":"both","popup":"Oracle's own measure: capex minus customer prepayments and vendor financing tied to capex, from its earnings release table. Company-defined; the tagged cash-flow line is larger, and the gap is the customer- and vendor-funded slice.","source":"Oracle's 8-K exhibit 99.1 quarterly reconciliation table as printed","aliases":["net cash outlay","net cash outlay for capex (Oracle)"]},
{"term":"net debt","kind":"metric","side":"both","popup":"Gross debt minus cash and marketable securities: borrowings after the cash that could repay them. Negative is net cash; a line crossing zero is the moment a company stops being a net creditor.","source":"This site's own definition: gross debt − cash − marketable securities, on tagged balances"},
{"term":"net debt/EBITDA","kind":"metric","side":"lender","popup":"Debt minus cash, divided by EBITDA. The cleaner leverage measure for a cash-rich company; the one the site's existing ratio catalog already computes.","source":"This site's own ratio catalog (net debt ÷ annualized EBITDA); this site's disclosed-only rule for BDC borrowers","aliases":["net debt to EBITDA","net leverage"]},
{"term":"net increase in net assets from operations","kind":"metric","side":"lender","popup":"A BDC's bottom line: NII plus realized and unrealized gains and losses. It moves with the marks, so it is noisier than NII and is never used to derive the fourth quarter.","source":"BXSL 10-Q 2026-06-30"},
{"term":"net interest margin","kind":"metric","side":"lender","popup":"Weighted-average yield on the debt portfolio at cost minus the BDC's cost of debt, in percentage points. The spread the BDC keeps for taking credit risk with borrowed money.","source":"This site's own ratio on the scorecard's yield at cost and cost of debt; BXSL 10-Q 2026-06-30, Item 3, for the sensitivity table","aliases":["NIM"]},
{"term":"net investment income","kind":"metric","side":"lender","popup":"Interest, dividends and fees earned on the portfolio, minus the fund's expenses and taxes. Excludes any change in the value of the loans. Includes PIK income that has been accrued but not received in cash.","source":"BXSL 10-Q 2026-06-30 (the income-recognition and incentive-fee notes)"},
{"term":"Net percentage","kind":"metric","side":"market","popup":"In SLOOS, the share of banks tightening minus the share loosening (or stronger demand minus weaker). Zero means the two sides balance.","source":"FRED series titles for DRTSCILM and DRSDCILM"},
{"term":"New-issue","kind":"market","side":"market","popup":"A loan being made now, at today's terms, as opposed to one already outstanding and trading. New-issue spreads show where the market is pricing risk this month.","source":"LCD US Private Credit Monitor, August 2026, slide 43 methodology"},
{"term":"new-issue spread","kind":"metric","side":"both","popup":"The yield premium over Treasuries at which a bond tranche priced, from its pricing term sheet. Not a secondary level and not an OAS, so it is drawn on its own axis beside the index, never subtracted from it.","source":"The issuer's FWP pricing term sheet as printed (SEC EDGAR form type FWP); LCD's new-issue direct-lending spreads for loans","aliases":["new-issue spreads","issue spread"]},
{"term":"NFCI","expansion":"Chicago Fed National Financial Conditions Index","kind":"series-id","side":"market","popup":"A weekly gauge of how easy or hard it is to get money in US markets. Zero is average; above zero is tighter than normal, below zero is looser.","source":"FRED series page https://fred.stlouisfed.org/series/NFCI, Notes block, fetched 2026-09-11"},
{"term":"NII","expansion":"net investment income","kind":"acronym","side":"lender","popup":"A BDC's earnings from interest and fees after its costs, before gains and losses on the loans. It is the cash-like profit that pays the dividend.","source":"BXSL 10-Q 2026-06-30 (income definition used for the fee)"},
{"term":"NII per share","expansion":"net investment income per share","kind":"metric","side":"lender","popup":"The quarter's net investment income divided by the weighted average shares: the earnings that fund the dividend, per share. Read it against the regular dividend per share.","source":"us-gaap investment-company taxonomy element InvestmentCompanyInvestmentIncomeLossPerShare, tagged by ARCC, BXSL, MAIN, OBDC, FSK and GBDC on SEC EDGAR companyfacts (checked 2026-09-10)"},
{"term":"NII return on NAV","kind":"metric","side":"lender","popup":"Annualized net investment income divided by average net assets: what the book earns for shareholders before marks. The BDC analogue of return on equity from earnings alone.","source":"us-gaap taxonomy elements NetInvestmentIncome and StockholdersEquity on SEC EDGAR companyfacts; this site's own ratio","aliases":["NII return","return on NAV"]},
{"term":"non-accrual","kind":"metric","side":"lender","popup":"A loan the BDC has stopped booking interest on because it doubts it will be paid in full. The closest thing private credit has to a default rate. BXSL: 3.6% of cost, 1.8% of fair value at June 30, 2026.","source":"BXSL 10-Q 2026-06-30","aliases":["non-accruals","nonaccrual"]},
{"term":"non-controlled affiliate","kind":"regulation","side":"lender","popup":"A portfolio company in which the BDC owns 5% to 25% of the voting stock: enough to be an 'affiliated person' under the 1940 Act, not enough to control it.","source":"15 U.S.C. §80a-2(a)(3) (law.cornell.edu); BXSL 10-Q 2026-06-30"},
{"term":"non-recourse debt","kind":"instrument","side":"both","popup":"Debt raised by a subsidiary that holds the financed assets and contracts, where lenders can look only to those assets. A bankruptcy-remote entity is not automatically non-recourse; the collateral sentence says how far.","source":"The filer's debt note as printed; BXSL 10-Q 2026-06-30 for the BDC-side SPV facilities","aliases":["SPV and non-recourse debt","non-recourse","bankruptcy-remote"]},
{"term":"OAS","expansion":"Option-adjusted spread","kind":"metric","side":"market","popup":"Option-adjusted spread: the extra yield a bond pays over Treasuries after allowing for any call option, in basis points. Five of the six ICE BofA tiles here are OAS; the sixth is an effective yield.","source":"ICE definition as given in the FRED Notes for BAMLH0A0HYM2 and BAMLH0A1HYBB (fetched 2026-09-11)"},
{"term":"OID","expansion":"Original issue discount","kind":"instrument","side":"market","popup":"Original issue discount: the loan is sold below face value, say at 99 instead of 100. The discount is extra return to the lender on top of the spread, paid up front.","source":"Usage: PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026. Definition is standard."},
{"term":"OID accretion","expansion":"original issue discount accretion","kind":"metric","side":"lender","popup":"When a loan is issued below par, the discount is booked into income a little each period until maturity. It lifts reported yield without any cash arriving and stops when a loan goes on non-accrual.","source":"BXSL 10-Q 2026-06-30"},
{"term":"one stop","kind":"instrument","side":"lender","popup":"Golub's name for its unitranche: a single senior secured loan covering the whole debt need. GBDC's book is 87% one stop at cost, which the site counts as first lien.","source":"GBDC's schedule of investments (the 'one stop' label and its totals at cost); this site's lien-mix mapping"},
{"term":"operating expense ratio","kind":"metric","side":"lender","popup":"Annualized running costs excluding interest, as a share of average net assets: 4 × (total expenses − interest) ÷ average net assets. The one cost measure that compares internal and external managers.","source":"us-gaap investment-company taxonomy elements InvestmentCompanyExpenseRatioIncludingIncentiveFee and InvestmentCompanyExpenseRatioBeforeIncentiveAllocation on SEC EDGAR companyfacts; this site's own ratio"},
{"term":"Option-adjusted spread","kind":"metric","side":"market","popup":"The extra yield a bond pays over Treasuries after allowing for any call option, in basis points. Five of the six ICE BofA tiles here are OAS; the sixth is an effective yield.","source":"ICE definition via FRED Notes for BAMLH0A0HYM2","aliases":["option-adjusted spreads"]},
{"term":"Payment default","kind":"metric","side":"market","popup":"The traditional default: a missed interest or principal payment, or a bankruptcy filing.","source":"PitchBook 2023 Annual Global Private Debt Report"},
{"term":"payment-in-kind","kind":"instrument","side":"lender","popup":"A loan feature that lets the borrower pay some or all interest in more debt. Shown on a holding as 'SOFR + 5.25% (incl. 2.88% PIK)'. Fine when agreed at signing; a warning when added later.","source":"BXSL 10-Q 2026-06-30; the BXSL 10-Q XBRL instance (accession 0001736035-26-000016)","aliases":["paid-in-kind"]},
{"term":"peers","kind":"metric","side":"lender","popup":"The eight BDCs closest to the one selected, by portfolio size, first-lien share and non-accrual rate. Drawn only from the 50 listed BDCs, never from operating companies.","source":"This site's own BDC distance, applied to the 50 listed BDCs only"},
{"term":"Percentile","kind":"metric","side":"market","popup":"Where today's value ranks against its own history: the 18th percentile means it has been lower only 18% of the time in the window shown on the tile.","source":"This site's own construction: the rank of the latest value among the observations dated within the window named on the tile"},
{"term":"PIK","expansion":"payment-in-kind","kind":"acronym","side":"lender","popup":"Interest paid by adding to the loan balance instead of in cash. The BDC books it as income now and collects it at maturity, if at all. A rising PIK share with flat NII means cash earnings are falling.","source":"BXSL 10-Q 2026-06-30"},
{"term":"PIK preferred","expansion":"payment-in-kind preferred units","kind":"instrument","side":"both","popup":"Preferred units whose dividend accrues instead of being paid in cash, often with rate step-ups over time. Equity in form, debt in cost: the most expensive capital in the build-out ledger.","source":"The issuer's 8-K or note as printed; the same PIK mechanism as the BDC-side PIK entry","aliases":["PIK preferred units"]},
{"term":"PitchBook","kind":"market","side":"market","popup":"The private-markets data vendor behind the fundraising, AUM, dry-powder and fund-performance series here, drawn from its annual private debt reports and a fund-overview workbook. Its LCD unit covers the loan market.","source":"The study material: 2024 Annual Global Private Debt Report, Q3 2026 Quantitative Perspectives: US Market Insights, Q2 2026 Global Private Market Fundraising Report, PitchBook Fund Benchmarks: Data and Methodology, and the PitchBook Fund Overview workbook (downloaded 2026-09-10)"},
{"term":"PME","expansion":"public market equivalent","kind":"acronym","side":"market","popup":"What the same cash flows would have earned in a public index. The Kaplan-Schoar version is a ratio: above 1.0× the fund beat the index. Direct alpha is the annualized form. Not computed on this site.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Public market equivalents (PMEs)'","aliases":["public market equivalent","KS-PME","direct alpha"]},
{"term":"portfolio company","kind":"instrument","side":"lender","popup":"A business the BDC has lent to or invested in. The count is a diversification measure: BXSL had 313 at June 30, 2026.","source":"BXSL 10-Q 2026-06-30; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"premium/discount","kind":"metric","side":"lender","popup":"Price to NAV expressed as a gap: 1.05× is a 5% premium, 0.95× a 5% discount. A lasting discount says the market expects losses the book has not yet taken.","source":"15 U.S.C. §80a-62(2) (law.cornell.edu)"},
{"term":"price to NAV","kind":"metric","side":"lender","popup":"Share price ÷ NAV per share: the market's opinion of the manager's marks. Above 1.0× the BDC can grow by issuing stock; below 1.0× it needs a shareholder vote to do so.","source":"15 U.S.C. §80a-62(2) (law.cornell.edu)"},
{"term":"Prime rate","kind":"market","side":"market","popup":"The base rate US banks post for their best business customers. Small-business loans and revolvers are often priced off it rather than SOFR.","source":"FRED Notes for DPRIME (fetched 2026-09-11)"},
{"term":"priority","kind":"instrument","side":"lender","popup":"Who gets paid first when a borrower fails: secured lenders, then unsecured, then subordinated, then equity. A lender's place in that queue matters more than its interest rate.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets; standard capital-structure vocabulary"},
{"term":"Private credit","kind":"market","side":"market","popup":"Lending by funds and other non-banks rather than by banks, to companies that are too small or too indebted for the public bond and syndicated loan markets.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"Private debt","kind":"market","side":"market","popup":"PitchBook's name for the fund universe: direct lending, mezzanine, distressed, special situations, real estate, infrastructure, venture and bridge debt funds. Used interchangeably with private credit.","source":"PitchBook 2024 Annual Global Private Debt Report"},
{"term":"private-credit share of the ledger","kind":"metric","side":"both","popup":"The portion of signed build-out financing provided by non-bank funds: private credit facilities plus fund-partnered joint ventures, divided by all signed rows. Stated with and without press-sourced rows.","source":"This site's own deal-ledger method","aliases":["private-credit share"]},
{"term":"purchase obligation and contractual commitment","kind":"regulation","side":"both","popup":"Non-cancelable promises to buy goods, services, capacity or power. Take-or-pay exposure that behaves like debt in a downturn. Each filer defines it differently, so the panel never sums it across companies.","source":"us-gaap taxonomy elements ContractualObligation, LongTermPurchaseCommitmentAmount and UnrecordedUnconditionalPurchaseObligationBalanceSheetAmount; the filer's commitments note","aliases":["purchase obligation","purchase obligations","contractual commitment","contractual commitments"]},
{"term":"Rating","expansion":"Credit rating","kind":"market","side":"market","popup":"A credit agency's letter grade for how likely a borrower is to repay. AAA to BBB- is investment grade; BB+ and below is high yield.","source":"ICE definition via FRED Notes for BAMLH0A0HYM2; LCD US Private Credit Monitor, August 2026, slide 43"},
{"term":"rating action","kind":"regulation","side":"both","popup":"An agency's assignment, affirmation, outlook change or move of a rating. On this site it is always a row with a date, agency and trigger sentence, never a number, and press-dated rows are drawn hollow.","source":"Moody's, S&P Global Ratings and Fitch press releases as dated; this site's own recording rule","aliases":["rating actions"]},
{"term":"Real estate debt","kind":"market","side":"market","popup":"Lending against property: mostly direct loans for real estate acquisitions, sometimes trading securitized property loans. One of PitchBook's nine private debt fund types.","source":"PitchBook 2024 Annual Global Private Debt Report, 'Fund type definitions'"},
{"term":"realized and unrealized gains","kind":"metric","side":"lender","popup":"Realized: the profit or loss locked in when a loan is repaid, sold or written off. Unrealized: the change in the marks on loans still held. Both sit below NII and drive NAV.","source":"BXSL 10-Q 2026-06-30"},
{"term":"rebased to 100","kind":"metric","side":"both","popup":"Each series divided by its own first value and multiplied by 100, so two prices that start at different levels can be read as growth from a common start. 125 means up 25% since the first month.","source":"Standard index construction; this site's own chart method","aliases":["rebased"]},
{"term":"Recession shading","kind":"metric","side":"market","popup":"Gray bands marking US recessions on a chart. The strategy page uses a hard-coded list of three recessions since 2001; the credit page derives bands from FRED's USREC series so the long-run charts are covered.","source":"FRED series page https://fred.stlouisfed.org/series/USREC, Notes block, fetched 2026-09-11","aliases":["recession bands"]},
{"term":"reconciliation gate","kind":"metric","side":"lender","popup":"The check a parsed schedule must pass before it is served: the sum of the loans read from the filing must match the tagged portfolio totals. Fail, and the site records the refusal with its reason instead of showing wrong numbers.","source":"This site's own parse rule: the schedule of investments must reconcile to InvestmentOwnedAtCost and InvestmentOwnedAtFairValue on SEC EDGAR companyfacts"},
{"term":"recovery","kind":"metric","side":"lender","popup":"The share of principal a lender gets back after a default, through repayment, restructuring or sale of the collateral. Higher priority and lower LTV mean higher recovery.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets; standard credit vocabulary"},
{"term":"Recovery rate","kind":"metric","side":"market","popup":"How much of a defaulted loan lenders eventually get back, as a share of face value. Fast, out-of-court fixes recover more than long bankruptcies.","source":"PitchBook 2023 Annual Global Private Debt Report; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"Refinancing","kind":"market","side":"market","popup":"Replacing an existing loan with a new one, usually to cut the rate, push out the maturity or change lenders.","source":"PitchBook 2024 Annual Global Private Debt Report; LCD US Private Credit Monitor, August 2026, slides 39-41"},
{"term":"regular vs supplemental vs special dividend","kind":"metric","side":"lender","popup":"Regular is the base quarterly payout the board intends to keep. Supplemental is an extra tied to excess income; special is a one-off, often from gains or spillover. Coverage is read against each.","source":"BXSL 10-Q 2026-06-30"},
{"term":"Repricing","kind":"market","side":"market","popup":"A borrower asking existing lenders to cut the spread on a loan, without new money, because the market has tightened. Common when loans trade above par.","source":"Usage: PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026; PitchBook 2024 Annual Global Private Debt Report. Definition is standard."},
{"term":"residual value guarantee","kind":"instrument","side":"both","popup":"The tenant's promise to make the owner whole if the asset is worth less than a set amount at the end of the lease. No liability is recorded, but it is the credit term that makes a campus bond investment grade.","source":"ASC 842 lessee disclosures of residual value guarantees; the filer's leases or commitments note as printed","aliases":["RVG","residual value guarantees"]},
{"term":"revolver","expansion":"revolving credit facility","kind":"instrument","side":"lender","popup":"A credit line that can be drawn, repaid and redrawn. On the asset side it is a commitment to a borrower; on the liability side it is the BDC's own bank line, whose undrawn room is its liquidity.","source":"BXSL 10-Q 2026-06-30","aliases":["revolving credit facility","revolvers"]},
{"term":"RIC","expansion":"regulated investment company","kind":"acronym","side":"lender","popup":"A tax status under Subchapter M of the tax code. A BDC that qualifies pays no corporate tax on income it distributes, which is why nearly all of its NII goes out as dividends.","source":"BXSL 10-Q 2026-06-30"},
{"term":"risk-rating mix","expansion":"internal risk-rating mix","kind":"metric","side":"lender","popup":"How the BDC grades its own loans, usually on a 1-to-5 scale, as a share of the portfolio. Disclosed-only and not comparable across BDCs, whose scales differ.","source":"The BDC's own 10-Q internal risk-rating table (not tagged on SEC EDGAR companyfacts, checked 2026-09-10); this site's disclosed-only rule","aliases":["risk rating","internal risk ratings","risk-rating"]},
{"term":"RPO","expansion":"remaining performance obligations","kind":"acronym","side":"both","popup":"Contracted revenue not yet recognized: the backlog a company has signed but not delivered. Undiscounted and spread over multi-year terms; the numerator of backlog to debt.","source":"us-gaap taxonomy element RevenueRemainingPerformanceObligation (ASC 606-10-50-13); each filer's revenue note","aliases":["remaining performance obligations","remaining performance obligation"]},
{"term":"RVPI","expansion":"remaining value to paid-in capital","kind":"acronym","side":"market","popup":"What a fund still holds, at the manager's marks, divided by the capital paid in. The unrealized part of the multiple; it should fall toward zero as the fund winds up. Not computed on this site.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Multiples'"},
{"term":"S&P","expansion":"S&P Global Ratings","kind":"market","side":"market","popup":"One of the three big rating agencies. Its financial-risk bands (debt/EBITDA under 1.5x minimal, over 5x highly leveraged) give the Underwriting view its leverage scale.","source":"S&P 2009 corporate ratings criteria, financial-risk matrix Table 2 (efis.psc.mo.gov/Document/Display/44676); FRED Notes for BAMLH0A0HYM2","aliases":["S&P Global Ratings","S&P Global"]},
{"term":"S&P financial-risk bands","kind":"metric","side":"lender","popup":"S&P's six-step ladder from minimal to highly leveraged, set by debt/EBITDA and FFO/debt. The site uses it to place every covered company and to measure covenant headroom.","source":"S&P 2009 corporate ratings criteria, financial-risk matrix (efis.psc.mo.gov/Document/Display/44676)"},
{"term":"SBA debentures","expansion":"Small Business Administration debentures","kind":"instrument","side":"lender","popup":"Long-dated, government-guaranteed borrowings raised by a BDC's SBIC subsidiary. Filers with SEC relief leave them out of the asset-coverage test, so their ratio looks higher than the raw formula gives.","source":"15 U.S.C. §80a-60(a)(5) (law.cornell.edu, fetched 2026-09-11)"},
{"term":"schedule of investments","kind":"regulation","side":"lender","popup":"The loan-by-loan table in every BDC 10-Q and 10-K: borrower, lien type, spread, rate, maturity, principal, cost, fair value and footnotes such as non-accrual. It is the raw material of the holdings table.","source":"The BXSL 10-Q XBRL instance (accession 0001736035-26-000016) and its HTML schedule of investments table"},
{"term":"SEC BDC data set","kind":"series-id","side":"lender","popup":"The SEC's monthly zip of every BDC's tagged financial statements and schedule of investments, flattened into tab-separated tables. One download covers every loan of every BDC that filed that month.","source":"SEC BDC data set readme.htm (2026_07_bdc.zip, sec.gov)"},
{"term":"Second lien","kind":"instrument","side":"market","popup":"A secured loan that ranks behind the first lien. It is repaid only after first-lien lenders, so it pays a higher spread and takes losses sooner.","source":"PitchBook 2024 Annual Global Private Debt Report; MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"Secondary market","kind":"market","side":"market","popup":"Where existing loans and bonds change hands after issue. Syndicated loans trade here; direct loans generally do not.","source":"LCD US Private Credit Monitor, August 2026, slide 43; PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026"},
{"term":"sector mix","kind":"metric","side":"lender","popup":"The portfolio split by borrower industry, top ten. Commercial services and software dominate BDC books (21.2% and 17.9% of holdings by count, LCD Q2 2026). Read point changes with a small-base caveat.","source":"LCD US Private Credit Monitor, August 2026, slide 30; the same deck, chart 24 series 2Q26 (Commercial Services 0.2117, Software 0.1787)"},
{"term":"senior loan program","kind":"instrument","side":"lender","popup":"ARCC's joint venture that holds first-lien loans and funds them with its own debt; ARCC holds subordinated certificates yielding 13.2%. A vehicle, not a loan.","source":"ARCC 10-Q 2026-06-30 (the yield table and the SDLP disclosure); SEC BDC data set, July 2026 soi.tsv (the SDLP fair-value subtotal row)"},
{"term":"senior securities","kind":"regulation","side":"lender","popup":"In the 1940 Act, a fund's debt and preferred stock: anything that ranks ahead of common shareholders. Asset coverage is measured against senior securities that are debt.","source":"15 U.S.C. §80a-18(g) (law.cornell.edu); BXSL 10-Q 2026-06-30"},
{"term":"severity stripe","kind":"metric","side":"lender","popup":"The colored edge on a scorecard row when a fixed rule trips: regular dividend coverage under 1.0× for two straight quarters, asset-coverage cushion under 15%, non-accruals over 3% of cost, or price/NAV below the universe's 25th percentile.","source":"This site's own reading rules for the Lenders scorecard"},
{"term":"SLOOS","expansion":"Senior Loan Officer Opinion Survey","kind":"acronym","side":"market","popup":"The Fed's quarterly survey of senior loan officers on whether their banks are tightening or loosening lending terms and seeing more or less demand.","source":"FRED Notes for DRTSCILM, DRTSCIS and DRSDCILM (fetched 2026-09-11)"},
{"term":"SOFR","expansion":"Secured Overnight Financing Rate","kind":"series-id","side":"market","popup":"The overnight rate banks pay to borrow cash against Treasuries. It is the base rate for almost every floating-rate loan, so when SOFR moves, every borrower's interest bill moves with it.","source":"New York Fed SOFR page https://www.newyorkfed.org/markets/reference-rates/sofr (fetched 2026-09-11); the FRED page for SOFR carries no notes; history start from the FRED series page"},
{"term":"SOFR90DAYAVG","expansion":"90-Day Average SOFR","kind":"series-id","side":"market","popup":"A three-month-style base rate that stands in for the term SOFR most loans reset off, which FRED does not carry. Used here to back the spread out of LCD's all-in rate.","source":"FRED series page https://fred.stlouisfed.org/series/SOFR90DAYAVG, Notes block, fetched 2026-09-11"},
{"term":"soi.tsv","kind":"series-id","side":"lender","popup":"The schedule-of-investments table inside the SEC BDC data set: one row per holding per filing, with cost, fair value, principal, spread, rate, PIK rate and floor already pivoted into columns.","source":"SEC BDC data set readme.htm (2026_07_bdc.zip, sec.gov), column names and the row rule"},
{"term":"SONIA","expansion":"Sterling Overnight Index Average","kind":"acronym","side":"both","popup":"The UK's overnight sterling rate, published by the Bank of England. Sterling loans in a BDC book reset off SONIA instead of SOFR, so spreads on the page are 'over base', not 'over SOFR'.","source":"Bank of England SONIA page (bankofengland.co.uk/markets/sonia-benchmark); BXSL 10-Q 2026-06-30 schedule footnote 2"},
{"term":"sources and uses","kind":"metric","side":"both","popup":"A cash-flow bridge for one fiscal year. Sources: operating cash flow, debt raised, converts, equity and preferred, partner and customer funding, cash drawdown. Uses: capex, buybacks, dividends, debt repaid.","source":"Each filer's cash-flow statement and financing notes; this site's own chart method","aliases":["sources and uses of cash"]},
{"term":"Special situations","kind":"market","side":"market","popup":"Opportunistic lending or structured equity, such as convertible debt or debt with warrants, made to gain influence or control over a company that is usually in some distress.","source":"PitchBook 2024 Annual Global Private Debt Report","aliases":["Credit special situations"]},
{"term":"spillover","expansion":"undistributed taxable income","kind":"metric","side":"lender","popup":"Taxable income a BDC earned but has not yet paid out, carried into the next year. It is a reserve that can top up the dividend when a quarter's NII falls short.","source":"BXSL 10-Q 2026-06-30"},
{"term":"Sponsor-backed","expansion":"PE-backed","kind":"market","side":"market","popup":"A borrower owned by a private equity firm (the sponsor). Sponsors bring repeat business and can inject equity when a company stumbles, so lenders treat these loans differently.","source":"LCD US Private Credit Monitor, August 2026, slides 6-7, 23-24; PitchBook 2023 Annual Global Private Debt Report"},
{"term":"Spread over base","kind":"metric","side":"market","popup":"The lender's margin over the floating base rate, in basis points. It is the price of credit risk plus illiquidity on a private loan, before floors, discounts and fees.","source":"LCD US Private Credit Monitor, August 2026, slide 13 footnote"},
{"term":"Spread to maturity","expansion":"STM","kind":"metric","side":"market","popup":"A loan's spread over the base rate if held to maturity, counting the discount and fees as well as the coupon margin. The loan-market cousin of a bond's OAS.","source":"PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figures 52-53 and 94)"},
{"term":"SPV","expansion":"special purpose vehicle","kind":"instrument","side":"lender","popup":"A wholly owned subsidiary that holds a slice of the loans and borrows against them from a bank. The lender can only look to the SPV's assets, not the whole BDC.","source":"BXSL 10-Q 2026-06-30"},
{"term":"SRLN","expansion":"State Street Blackstone Senior Loan ETF","kind":"instrument","side":"market","popup":"The State Street Blackstone Senior Loan ETF (the SPDR name is the former one), an exchange-traded fund of syndicated senior loans. The default loan-market line on chart M8, drawn against BIZD.","source":"Yahoo chart v8 for SRLN, meta.longName (fetched 2026-09-11); State Street Global Advisors fund page for SRLN (ssga.com)","aliases":["SPDR Blackstone Senior Loan ETF"]},
{"term":"STLFSI4","expansion":"St. Louis Fed Financial Stress Index, version 4","kind":"series-id","side":"market","popup":"A weekly stress gauge built from 18 market series. Zero is normal; above zero means more stress than usual, below zero less.","source":"FRED series page https://fred.stlouisfed.org/series/STLFSI4, Notes block, fetched 2026-09-11"},
{"term":"structured","kind":"instrument","side":"lender","popup":"Holdings that are securities of a structure rather than loans to a company: CLO equity, joint-venture certificates, asset-backed notes. Grouped as 'vehicles' and kept out of the loan statistics.","source":"LCD US Private Credit Monitor, August 2026, slide 31 source line"},
{"term":"subordinated","kind":"instrument","side":"lender","popup":"Debt that ranks below the secured lenders and is paid only after them. Mezzanine is the classic form, often with warrants attached. It behaves more like equity when a borrower struggles.","source":"PitchBook 2024 Annual Global Private Debt Report; LCD US Private Credit Monitor, August 2026, slide 33 source line"},
{"term":"Syndication","kind":"market","side":"market","popup":"A bank underwriting a loan and then selling it down to many investors. The price can 'flex' up if buyers are scarce, which is the uncertainty direct lenders remove.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets"},
{"term":"T10Y2Y","expansion":"10-year minus 2-year Treasury spread","kind":"series-id","side":"market","popup":"The 10-year Treasury yield minus the 2-year. Negative (inverted) has preceded most US recessions; positive is the normal shape.","source":"FRED series page https://fred.stlouisfed.org/series/T10Y2Y, Notes block, fetched 2026-09-11"},
{"term":"Takeout","kind":"market","side":"market","popup":"When a borrower repays a loan from one market by raising a new one in the other: a private loan refinanced by a syndicated loan, or the reverse.","source":"LCD US Private Credit Monitor, August 2026, slides 38-41 titles and chartHeadings"},
{"term":"target leverage","kind":"metric","side":"lender","popup":"The debt-to-equity range the manager says it aims to run at, stated in the 10-Q. Compare with actual gross and net debt-to-equity and with the statutory cushion.","source":"The BDC's own stated target debt-to-equity range, from its 10-Q or earnings release; this site's disclosed-only rule"},
{"term":"term SOFR","expansion":"CME Term SOFR reference rate","kind":"market","side":"market","popup":"A forward-looking SOFR for one or three months ahead, set by CME from SOFR futures. Most loans reset off it, but FRED does not carry it, so the site uses the 90-day average SOFR as the stand-in.","source":"CME Group Term SOFR reference rates page (cmegroup.com/market-data/cme-group-benchmark-administration/term-sofr.html); BXSL 10-Q 2026-06-30 (accession 0001736035-26-000016), credit-facility note","aliases":["CME Term SOFR"]},
{"term":"TLB","expansion":"Term loan B","kind":"instrument","side":"market","popup":"Term loan B: the standard institutional leveraged loan. Floating rate, five to seven years, little or no scheduled repayment, sold to CLOs and loan funds.","source":"Usage: PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026. Definition is standard."},
{"term":"top-10 concentration","kind":"metric","side":"lender","popup":"The share of the portfolio in the ten largest borrowers. Higher means one bad loan hurts more. Computed on third-party debt so a joint venture does not dominate the list.","source":"This site's own ratio on the parsed schedule of investments (the ten largest issuers ÷ total fair value)"},
{"term":"total return on NAV","kind":"metric","side":"lender","popup":"The return a shareholder earned on book value: change in NAV per share plus dividends, divided by starting NAV. BXSL: 1.2% for the first half of 2026. Shown YTD or trailing four quarters, never as one quarter unless tagged.","source":"BXSL 10-Q 2026-06-30"},
{"term":"total-investment-income yield","expansion":"total investment income yield on average cost","kind":"metric","side":"lender","popup":"Annualized total investment income divided by the average portfolio at cost. Interest plus dividends, fees and PIK over everything held, so it is broader than the yield on debt investments.","source":"us-gaap taxonomy elements GrossInvestmentIncomeOperating and InvestmentOwnedAtCost on SEC EDGAR companyfacts (tagged by 40 of 50 in frames); this site's own composite ratio","aliases":["total investment income yield","income yield on cost"]},
{"term":"total-return lookback","kind":"metric","side":"lender","popup":"A fee test over several quarters (BXSL: twelve) that reduces the income fee if the BDC has taken capital losses. Without it, the manager can collect income fees while NAV falls.","source":"BXSL 10-Q 2026-06-30"},
{"term":"TOTBKCR","expansion":"Total bank credit, all commercial banks","kind":"series-id","side":"market","popup":"Total bank credit: all loans and securities held by US commercial banks. The denominator for the 'share of bank credit' tile.","source":"FRED series page https://fred.stlouisfed.org/series/TOTBKCR, Notes block, fetched 2026-09-11"},
{"term":"TTM","expansion":"Trailing twelve months","kind":"metric","side":"market","popup":"Trailing twelve months: the last four quarters added together, whatever the calendar year. PitchBook reports TTM inflows among the top seven US alternative asset managers.","source":"PitchBook 2023 Annual Global Private Debt Report; PitchBook 2024 Annual Global Private Debt Report"},
{"term":"TVPI","expansion":"total value to paid-in capital","kind":"acronym","side":"market","popup":"Everything a fund has returned plus what it still holds, divided by the capital paid in. TVPI = DPI + RVPI. A multiple, so it ignores how long the money was out. Not computed on this site.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025), 'Multiples'"},
{"term":"typed member","kind":"series-id","side":"lender","popup":"An XBRL dimension value the filer types in as free text, such as 'Issuer name N | affiliation', instead of picking from a fixed list. Each loan in a BDC schedule is one typed member.","source":"SEC BDC data set readme.htm (2026_07_bdc.zip, sec.gov), NUM table segments field; the BXSL 10-Q XBRL instance (InvestmentIdentifierAxis typed members)"},
{"term":"unfunded commitment","kind":"metric","side":"lender","popup":"Money the BDC has promised to lend but has not yet handed over, mostly on revolvers and delayed-draw loans. It must be fundable from cash and undrawn lines, and it counts when planning leverage.","source":"BXSL 10-Q 2026-06-30"},
{"term":"Unitranche","kind":"instrument","side":"market","popup":"One loan that does the job of senior and junior debt together, with a single blended rate. It is the standard private-credit structure; about nine in ten private loans are unitranches.","source":"MFA and Proskauer, The Role of Private Credit in U.S. Capital Markets; PitchBook 2024 Annual Global Private Debt Report","aliases":["unitranche loans"]},
{"term":"unsecured notes","kind":"instrument","side":"lender","popup":"Bonds the BDC issues with no specific collateral. Their indentures usually require the BDC to keep meeting the 1940 Act asset-coverage test, so the statutory ratio is also a bond covenant.","source":"BXSL 10-Q 2026-06-30"},
{"term":"Use of proceeds","kind":"market","side":"market","popup":"What a loan is for. LCD's categories on slide 8 are LBO/M&A, refinancing, recapitalization (which includes dividend recaps) and other.","source":"LCD US Private Credit Monitor, August 2026, slide 8 title and chartHeading"},
{"term":"USPP","expansion":"US private placement","kind":"acronym","side":"both","popup":"A bond sold directly to a small group of institutional investors, often insurers, without a public registration. A financing channel in the build-out ledger beside bank loans, public notes and private credit facilities.","source":"This site's own deal-ledger channel; the filing or press release as printed per row","aliases":["US private placement"]},
{"term":"USREC","expansion":"NBER recession indicator","kind":"series-id","side":"market","popup":"A 1/0 flag for recession months: from the month after the NBER peak through the trough. The dashboard shades those months gray on every long chart so you can see how a series behaved in past downturns.","source":"FRED series page https://fred.stlouisfed.org/series/USREC, Notes block, fetched 2026-09-11"},
{"term":"vehicles","kind":"instrument","side":"lender","popup":"Capital a BDC puts to work through a structure it owns or co-owns (a joint venture, loan program, asset manager, CLO equity, REIT) instead of a direct loan. Yield there comes partly from leverage inside the vehicle.","source":"ARCC 10-Q 2026-06-30 (the financial report's R2.htm and R4.htm; the Ivy Hill and SDLP disclosures); this site's own vehicle typing"},
{"term":"vendor financing","expansion":"OEM and software-license financing arrangements","kind":"instrument","side":"both","popup":"Equipment bought on deferred payment terms from the supplier: a balance in the debt note, not a flow in the issuance tags. A fourth channel beside delayed-draw loans, notes and converts.","source":"The filer's debt note as printed (for example an 'OEM and Software License Financing Arrangements' line)","aliases":["vendor (OEM) financing","OEM financing"]},
{"term":"Venture debt","kind":"market","side":"market","popup":"Loans to venture-backed startups, used to extend runway to the next round or exit without giving up more equity.","source":"PitchBook 2024 Annual Global Private Debt Report"},
{"term":"Vintage","expansion":"Vintage year","kind":"metric","side":"market","popup":"The year a fund made its first investment. Funds are compared against others of the same vintage because they faced the same market.","source":"PitchBook Fund Benchmarks: Data and Methodology (September 29, 2025)"},
{"term":"watchlist","kind":"metric","side":"lender","popup":"The holdings that need a second look: every loan on non-accrual, every third-party loan marked under 0.80, and every loan paying PIK, each with the loss so far (cost − fair value).","source":"This site's own filter for the per-BDC drill-down"},
{"term":"weighted-average yield at cost and at fair value","kind":"metric","side":"lender","popup":"The average interest rate the debt book earns, weighted by each loan's size. At cost it is what the BDC paid for; at fair value it is what today's marks imply. BXSL: 9.2% at cost, 9.4% at fair value.","source":"BXSL 10-Q 2026-06-30"},
{"term":"XBRL","expansion":"eXtensible Business Reporting Language","kind":"acronym","side":"lender","popup":"The machine-readable tags embedded in SEC filings since 2009. Each number in a 10-Q carries a standard name (a tag), a period and units, which is what lets the site read 50 BDCs automatically.","source":"SEC EDGAR APIs page (sec.gov/search-filings/edgar-application-programming-interfaces, fetched 2026-09-11)"},
{"term":"yield on exits","kind":"metric","side":"lender","popup":"The weighted-average yield of the loans repaid or sold this quarter, as stated in the 10-Q. Disclosed-only. Higher than the yield on new loans means the book is being refinanced cheaper.","source":"BXSL 10-Q 2026-06-30 ('yield on investments fully sold or paid down'); this site's disclosed-only rule","aliases":["yield on investments fully sold or paid down","exit yield"]},
{"term":"yield on new investments","kind":"metric","side":"lender","popup":"The weighted-average yield of the loans the BDC made this quarter, as stated in its 10-Q. Disclosed-only: the site prints the filer's sentence and never computes it.","source":"BXSL 10-Q 2026-06-30 ('Weighted average yield of new investments'); this site's disclosed-only rule","aliases":["yield of new investments","new-investment yield"]},
{"term":"Yield to maturity","expansion":"YTM","kind":"metric","side":"market","popup":"The total annual return a loan or bond pays if held to maturity at today's price. For a floating-rate loan it is the base rate plus the spread to maturity.","source":"PitchBook Q3 2026 Quantitative Perspectives: US Market Insights (figure 52); PitchBook LCD US Leveraged Loan Daily Playbook, September 10, 2026"},
{"term":"YTD","expansion":"Year to date","kind":"metric","side":"market","popup":"Year to date: from January 1 to the latest data point. LCD compares YTD deal counts and volumes with the same point last year.","source":"LCD US Private Credit Monitor, August 2026, slides 5 and 14"},
{"term":"YTD fact","expansion":"year-to-date fact","kind":"series-id","side":"lender","popup":"A tagged number that covers the fiscal year so far, not one quarter. Most BDCs tag total return, NII per share, distributions and PIK this way, so the site subtracts the prior YTD to get the quarter.","source":"SEC XBRL frames, CY2026Q2, for the three-month coverage counts; this site's own year-to-date fill rule"},
{"term":"Z-score","kind":"metric","side":"market","popup":"How far a reading sits from its own average, in standard deviations. Zero is normal; plus 2 is unusually high, minus 2 unusually low. PitchBook colors its dashboards by it.","source":"PitchBook Q3 2026 Quantitative Perspectives: US Market Insights"}
];

  /* ---------- lookup ---------- */

  /* Lower-cased term and alias -> entry. Two entries never share a key:
     the generator refuses a glossary where they do. */
  var INDEX = {};
  TERMS.forEach(function (t) {
    INDEX[t.term.toLowerCase()] = t;
    (t.aliases || []).forEach(function (a) { INDEX[a.toLowerCase()] = t; });
  });
  var index = {
    get: function (key) { return INDEX[String(key).toLowerCase()] || null; },
    has: function (key) { return Object.prototype.hasOwnProperty.call(INDEX, String(key).toLowerCase()); },
    keys: function () { return Object.keys(INDEX); },
    size: Object.keys(INDEX).length
  };
  function lookup(text) { return index.get(text); }

  /* ---------- the matcher ---------- */

  /* Acronyms and series ids match exactly ("NII", not "nii"; "SOFR", not
     "sofr"); so does any string with no lower-case letter, whatever its
     kind (an alias such as "DDTL" on an instrument). Phrases match in any
     case, so "Dividend coverage" at the start of a sentence still resolves. */
  function isSensitive(entry, s) {
    return entry.kind === "acronym" || entry.kind === "series-id" || !/[a-z]/.test(s);
  }
  function escapeRe(s) { return s.replace(/[.*+?^$\{\}()|[\]\\\/]/g, "\\$&"); }
  function anyCase(s) {
    return s.split("").map(function (ch) {
      var lo = ch.toLowerCase(), up = ch.toUpperCase();
      return lo !== up ? "[" + lo + up + "]" : escapeRe(ch);
    }).join("");
  }
  /* Every term and alias, longest first so "core NII" wins over "NII" at
     the same position; ties broken by text so the pattern is stable. */
  var KEYS = [];
  TERMS.forEach(function (t) {
    [t.term].concat(t.aliases || []).forEach(function (s) {
      KEYS.push({ text: s, sensitive: isSensitive(t, s) });
    });
  });
  KEYS.sort(function (a, b) {
    return b.text.length - a.text.length || (a.text < b.text ? -1 : a.text > b.text ? 1 : 0);
  });
  /* Whole words only: the character before is not alphanumeric (or there is
     none) and the character after is not alphanumeric. "$2,899B" does not
     contain the rating "B"; "BB / B / CCC" contains all three. */
  var PATTERN = new RegExp(
    "(^|[^A-Za-z0-9_])(" +
    KEYS.map(function (k) { return k.sensitive ? escapeRe(k.text) : anyCase(k.text); }).join("|") +
    ")(?![A-Za-z0-9_])", "g");

  /* Split a text into plain and matched segments. The first occurrence of
     each entry in a section is a match; later ones are plain, so 'seen'
     (entry term -> true) is shared by every text node of one section and
     mutated here. Pure apart from that: no DOM, so the test can run it. */
  function tokenize(text, seen) {
    var out = [], last = 0, m;
    PATTERN.lastIndex = 0;
    while ((m = PATTERN.exec(text))) {
      var matched = m[2], start = m.index + m[1].length;
      var entry = INDEX[matched.toLowerCase()];
      if (!entry || seen[entry.term]) continue;
      seen[entry.term] = true;
      if (start > last) out.push({ text: text.slice(last, start) });
      out.push({ text: matched, term: entry.term });
      last = start + matched.length;
    }
    if (!out.length) return null;
    if (last < text.length) out.push({ text: text.slice(last) });
    return out;
  }

  /* ---------- wrapping a page ---------- */

  var SKIP_TAGS = { CODE: 1, PRE: 1, SVG: 1, A: 1, BUTTON: 1, INPUT: 1, TEXTAREA: 1, SELECT: 1, SCRIPT: 1, STYLE: 1 };
  function skipped(el) {
    var tag = String(el.tagName || "").toUpperCase();
    if (SKIP_TAGS[tag]) return true;
    if (el.classList && (el.classList.contains("term") || el.classList.contains("metric-pop"))) return true;
    if (el.hasAttribute && (el.hasAttribute("data-no-terms") || el.hasAttribute("data-metric"))) return true;
    return false;
  }
  function matchesSel(el, sel) {
    if (el.matches) return el.matches(sel);
    return String(el.tagName || "").toLowerCase() === sel;
  }

  /* Wrap the first occurrence of each term inside every section of rootEl
     in <span class="term" tabindex="0" data-term="...">. Code, links,
     controls, SVG, the popup, anything under [data-no-terms] and the
     metric labels ([data-metric], which carry their own popup) are left
     alone, as is text already wrapped. Returns the number of spans made.
     opts.perSection is the section selector (default "section"); when
     rootEl contains none it is treated as one section. opts.document lets a
     test supply a document; the page never needs to. */
  function wrap(rootEl, opts) {
    opts = opts || {};
    var doc = opts.document || (typeof document !== "undefined" ? document : null);
    if (!rootEl || !doc) return 0;
    var sel = opts.perSection || "section";
    var sections = rootEl.querySelectorAll ? Array.prototype.slice.call(rootEl.querySelectorAll(sel)) : [];
    if (!sections.length) sections = [rootEl];
    var made = 0;
    sections.forEach(function (sec) {
      var seen = {};
      /* A second call must not wrap the second occurrence: what is already
         wrapped in this section counts as seen. */
      Array.prototype.forEach.call(sec.querySelectorAll("[data-term]"), function (el) {
        var e = INDEX[String(el.getAttribute("data-term")).toLowerCase()];
        if (e) seen[e.term] = true;
      });
      var walker = doc.createTreeWalker(sec, 4 /* NodeFilter.SHOW_TEXT */, {
        acceptNode: function (n) {
          var p = n.parentNode;
          while (p && p !== sec) {
            if (skipped(p)) return 2; /* FILTER_REJECT */
            if (p !== rootEl && matchesSel(p, sel)) return 2; /* a nested section walks itself */
            p = p.parentNode;
          }
          return 1; /* FILTER_ACCEPT */
        }
      });
      var nodes = [];
      while (walker.nextNode()) nodes.push(walker.currentNode);
      nodes.forEach(function (n) {
        var parts = tokenize(n.nodeValue, seen);
        if (!parts) return;
        var frag = doc.createDocumentFragment();
        parts.forEach(function (p) {
          if (!p.term) { frag.appendChild(doc.createTextNode(p.text)); return; }
          var span = doc.createElement("span");
          span.className = "term";
          span.tabIndex = 0;
          span.setAttribute("data-term", p.term);
          span.textContent = p.text;
          frag.appendChild(span);
          made++;
        });
        n.parentNode.replaceChild(frag, n);
      });
    });
    return made;
  }

  /* ---------- the popup ---------- */

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  /* Two parts and a source: the expansion beside the term, the popup text,
     then where it comes from. Pure, so the test can check the escaping. */
  function html(entry) {
    return "<h4>" + esc(entry.term) +
      (entry.expansion ? " <span class='pop-expansion'>" + esc(entry.expansion) + "</span>" : "") + "</h4>" +
      "<p>" + esc(entry.popup) + "</p>" +
      "<p class='pop-src'><span class='pop-tag'>Source</span>" + esc(entry.source) + "</p>";
  }

  var attached = false;
  /* Show the popup for a .term on hover and focus, hide it on leave, blur
     and Escape. popEl is the page's shared #metric-pop when it has one
     (the metric popups keep using it for [data-metric]; the two never
     overlap because a term is never wrapped inside a metric label), else
     a #term-tip is created. Calling attach twice is a no-op. */
  function attach(popEl) {
    if (attached || typeof document === "undefined") return;
    attached = true;
    var pop = popEl || document.getElementById("metric-pop");
    if (!pop) {
      pop = document.createElement("div");
      pop.id = "term-tip";
      pop.className = "metric-pop";
      pop.setAttribute("role", "tooltip");
      pop.hidden = true;
      document.body.appendChild(pop);
    }
    var popFor = null;
    function show(el) {
      var entry = INDEX[String(el.getAttribute("data-term") || "").toLowerCase()];
      if (!entry) return;
      popFor = el;
      pop.innerHTML = html(entry);
      pop.hidden = false;
      /* Below this width the popup is a bottom sheet positioned by CSS, as
         on the strategy page; inline offsets would strand it off-screen. */
      if (window.matchMedia && window.matchMedia("(max-width: 680px)").matches) {
        pop.style.left = ""; pop.style.top = ""; return;
      }
      var r = el.getBoundingClientRect(), pw = pop.offsetWidth, ph = pop.offsetHeight;
      var left = Math.min(r.left + window.scrollX,
        window.scrollX + document.documentElement.clientWidth - pw - 12);
      var top = r.bottom + window.scrollY + 8;
      if (r.bottom + ph + 20 > document.documentElement.clientHeight) {
        top = Math.max(window.scrollY + 8, r.top + window.scrollY - ph - 8);
      }
      pop.style.left = Math.max(window.scrollX + 8, left) + "px";
      pop.style.top = top + "px";
    }
    /* Only hide what this module showed: a metric popup in the same
       element is someone else's, and stays. */
    function hide(el) {
      if (!popFor) return;
      if (el && popFor !== el) return;
      pop.hidden = true;
      popFor = null;
    }
    function termOf(e) { return e.target && e.target.closest ? e.target.closest(".term[data-term]") : null; }
    document.addEventListener("mouseover", function (e) { var t = termOf(e); if (t) show(t); });
    document.addEventListener("mouseout", function (e) { var t = termOf(e); if (t) hide(t); });
    document.addEventListener("focusin", function (e) { var t = termOf(e); if (t) show(t); });
    document.addEventListener("focusout", function (e) { var t = termOf(e); if (t) hide(t); });
    document.addEventListener("keydown", function (e) { if (e.key === "Escape") hide(); });
  }

  return {
    VERSION: VERSION, TERMS: TERMS, index: index, lookup: lookup,
    tokenize: tokenize, wrap: wrap, attach: attach, html: html,
    pattern: PATTERN.source
  };
});
